const e={"/content/audio/bgm.json":{tracks:{menu:{en:"Menu · Before the trip"},title:{en:"Title theme · Pongso no Tao"},harbour_day:{en:"Kaiyuan Harbour · Island theme (day)"},night:{en:"Night"},sea:{en:"Open sea · Plank boat"},imorod:{en:"Imorod village"},ivalino:{en:"Ivalino village"},iranmeylek:{en:"Iranmeylek village"},mountain:{en:"Up the hills · Inland"}}},"/content/dialogue/elders-akes.json":{dialogues:{dlg_elder_f_yayo:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"What our family eats and stores — here in Yayo, that's my job."},{en:"Cooking and keeping food are women's skills."}],idle:[{lines:[{en:"The sun is good today. Let's put things out to dry."}]},{lines:[{en:"Have you eaten? If not, there's still taro in the pot."}]},{lines:[{en:"Put the dried flying fish away well. That's food for the whole year."}]},{lines:[{en:"Go easy on the winter stores."}]}],keeper:{invite:[{en:"Want to learn dried flying fish? Bring flying fish in the flying fish season and I'll show you."}],missing:[{en:"Not enough yet: {need}. Come back when you have it all."}],teach:[{en:"This is dried flying fish. Dry it, store it, and you'll have fish all winter."},{en:"Every family does it a bit differently. The details still need checking with the Tao community."}],after:[{en:"Take the dried fish out and check it often. Don't let it get damp."}]}},dlg_elder_f_iraraley:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"The fields of Iraraley — the yams and millet — I look after them."}],idle:[{lines:[{en:"The weeds in the field are back again."}]},{lines:[{en:"No field work at night. I'll go early tomorrow."}]},{lines:[{en:"The millet looks great. It should be a good harvest this year."}]},{lines:[{en:"What you plant in winter only shows in spring."}]}],keeper:{invite:[{en:"Want to learn boiled yam? Go dig up two yams by the hills."}],missing:[{en:"Not enough yet: {need}. Come back when you have it all."}],teach:[{en:"Peel the yam and boil it. That's all. Soft and easy on the stomach."},{en:"Every family does it a bit differently. The details still need checking with the Tao community."}],after:[{en:"Pick the right spot to dig yams. Don't dig up the whole patch."}]}},dlg_elder_f_iranmeylek:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"I grew up walking the tide flats of Iranmeylek. Ask me what you can pick and what you can't."}],idle:[{lines:[{en:"When is low tide today? Let's check the tide."}]},{lines:[{en:"You can go at low tide at night too, but bring a light and watch your step."}]},{lines:[{en:"The summer sea is gentle, and the tide flats are full of life."}]},{lines:[{en:"The waves are big in winter. Don't go too far out on the tide flats."}]}],keeper:{invite:[{en:"Want to learn boiled shellfish and seaweed? At low tide, pick two shellfish and two handfuls of seaweed."}],missing:[{en:"Not enough yet: {need}. Come back when you have it all."}],teach:[{en:"Wash them and boil them. Eat with taro or sweet potato. That's the taste of the sea."},{en:"Every family does it a bit differently. The details still need checking with the Tao community."}],after:[{en:"Remember: put the small ones back so they can grow."}]}},dlg_villager_taro:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"I look after the taro fields of Ivalino. The water has to flow and the weeds come out, or the taro won't grow well."}],idle:[{lines:[{en:"You can tell how the soli is doing just by its leaves."}]},{lines:[{en:"After dark, you can really hear the water in the fields."}]},{lines:[{en:"In the flying fish season the men go to sea, so the fields need even more care."}]},{lines:[{en:"The field water is cold in winter. Keep your hands and feet moving."}]}],keeper:{invite:[{en:"Want to learn boiled taro? Pick three taro."}],missing:[{en:"Not enough yet: {need}. Come back when you have it all."}],teach:[{en:"Wash and boil. The simplest dish, and the one we eat most."},{en:"Every family does it a bit differently. The details still need checking with the Tao community."}],after:[{en:"You need a full belly to get work done."}]}},dlg_weaver_elder:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"Weaving is passed down by the women of Imorod, generation to generation. The parts that can be shared, I'll teach you slowly."}],idle:[{lines:[{en:"Weaving is easiest to see in good light."}]},{lines:[{en:"My eyes aren't good at night. No more weaving."}]},{lines:[{en:"We don't weave during the flying fish season."}]},{lines:[{en:"Winter is the time for weaving. I sit for a whole afternoon."}]}],keeper:{invite:[{en:"Want to learn boiled flying fish? Bring two flying fish in the flying fish season."}],missing:[{en:"Not enough yet: {need}. Come back when you have it all."}],teach:[{en:"Boil the flying fish with simple seasoning. Some foods must never be cooked with flying fish. That's the rule."},{en:"Every family does it a bit differently. The details still need checking with the Tao community."}],after:[{en:"Remember the flying fish rules. The flying fish taught them to us."}]}},dlg_elder_f_iratay:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"I look after the sweet potato and taro fields of Iratay."},{en:"If you want something from the fields, ask first."}],idle:[{lines:[{en:"Sweet potatoes grow anywhere. Easy to plant and they keep well."}]},{lines:[{en:"Some nights the school is lively. The kids are practising songs."}]},{lines:[{en:"The summer sun is strong. Wear a hat in the fields."}]},{lines:[{en:"Winter sweet potatoes are extra sweet."}]}],keeper:{invite:[{en:"Want to learn taro and sweet potato? Bring one taro and one sweet potato."}],missing:[{en:"Not enough yet: {need}. Come back when you have it all."}],teach:[{en:"Boil them separately and eat them together as a meal. Simple, but filling."},{en:"Every family does it a bit differently. The details still need checking with the Tao community."}],after:[{en:"Remember to share some of what you dig up with the neighbours."}]}}}},"/content/dialogue/elders-akey.json":{dialogues:{dlg_elder_yayo:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"Going to sea in flying fish season, the nets, the boat crews — in Yayo, I keep an eye on all that."},{en:"The net feeds a whole family. When it tears, you mend it."}],idle:[{lines:[{en:"Boats come and go at the harbour, but the sea is still the same sea."}]},{lines:[{en:"It's night. Go home early. Tomorrow's sea can wait for tomorrow."}]},{lines:[{en:"Flying fish season is here. The boat crews get ready before dawn."},{en:"The alibangbang are back, and everyone is busy."}]},{lines:[{en:"Big waves in winter. A good time to mend nets at home."}]}]},dlg_elder_iraraley:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"Building a tatala, choosing wood up the mountain — in Iraraley, come to me."},{en:"A boat takes many people to build. It never belongs to just one."}],idle:[{lines:[{en:"The tide flats of Iraraley are huge. Go have a look at low tide."}]},{lines:[{en:"The mountain is dark at night. Don't go up alone."}]},{lines:[{en:"All the boats are in the water for flying fish season. This year's boats run well."}]},{lines:[{en:"In winter we decide which boat to fix first."}]}]},dlg_elder_iranmeylek:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"Ropes and paddles for the sea — in Iranmeylek, I'm the one who teaches that."},{en:"At sea you must see things for yourself. Don't rely on others."}],idle:[{lines:[{en:"Dongqing Bay gets the first light of morning — and the first tourists."}]},{lines:[{en:"Listen, the waves are getting louder. The wind will be stronger tomorrow."}]},{lines:[{en:"In flying fish season, keep the rules of the boat beach."}]},{lines:[{en:"The winter sea won't let us out, so we wait."}]}]},dlg_elder_ivalino:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"The flying fish rules and how to share the catch — the men of Ivalino decide together. I'm the oldest, so everyone asks me."}],idle:[{lines:[{en:"The old houses of Ivalino are still here. Our ancestors left them to us. If you want a photo, ask the owner first."}]},{lines:[{en:"At night, old folks just sit, listen to the sea, and think about the past."}]},{lines:[{en:"When sharing the fish, never forget the elders who can't get around."}]},{lines:[{en:"Winter wind is cold. The old houses stay warmer."}]}]},dlg_elder_imorod:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"I know the mountain best: goats, trees, mountain paths."},{en:"Go up the mountain with an adult. Don't wander off."}],idle:[{lines:[{en:"The goats on Mt. Hongtou have wandered far again."}]},{lines:[{en:"We don't go up the mountain at night. The mountain has its own rules."}]},{lines:[{en:"Imorod is where the flying fish story began."}]},{lines:[{en:"Grass grows slowly in winter, so the goats come down lower."}]}]},dlg_elder_iratay:{greet:[{en:"akokey! Come, sit for a bit."}],duty:[{en:"Boat crews going to sea and sharing fish in Iratay — just ask me."}],idle:[{lines:[{en:"Planes come and go, but we still paddle our boats."}]},{lines:[{en:"The boat beach is quiet at night. The boats are resting."}]},{lines:[{en:"In flying fish season, the Tao man can go to sea with our boat crew. Only men go."}]},{lines:[{en:"Strong winds in winter. Everyone sorts their fishing gear at home."}]}]}}},"/content/dialogue/legacy.json":{dialogues:{origins:{yayo:{en:"The sea breeze blows in from Kaiyuan Harbour. The shops and boat beach of Yayo are as lively as ever — welcome home.",taoEn:"Yayo — pongso no Tao. (teaching draft)"},iraraley:{en:"The roads of Iraraley are wide, and the tide flats are huge. The elders say people from Iranmeylek and Yayo always stopped to say hello when passing through.",taoEn:"Iraraley. (teaching draft)"},iranmeylek:{en:"Morning comes early to Dongqing Bay. Legend says the gods came down here. Today, the flying fish sea is right in front of you.",taoEn:"Iranmeylek. (teaching draft)"},ivalino:{en:"Ivalino keeps the most complete village of semi-underground houses. The stone walls and taro fields sit right beside it — daily life, out in the open.",taoEn:"Ivalino. (teaching draft)"},imorod:{en:"Imorod is where the flying fish legend began. The health station, the post office, Badai Bay and Little Orchid Island to the south — you see them all from here.",taoEn:"Imorod. (teaching draft)"},iratay:{en:"Iratay has little flat land, but it's the island's flattest place to launch to sea. In the wind off the runway, some come home and some just arrive.",taoEn:"Iratay. (teaching draft)"},visitor:{en:"The boat pulls into Kaiyuan Harbour. Please remember: plank boats, underground houses and fish-drying racks are the Tao people's life and property. Ask before you go near. Welcome — listen well and walk gently as a visitor.",taoEn:"Pongso no Tao. Maran kamo. (teaching draft)"}},elder_home:{speaker:{en:"Village elder"},lines:[{en:"Good to see you. Put these words in your notebook first: this island is Pongso no Tao, the Island of People."},{en:"The fish-calling festival is meyvanwa, the flying fish season is rayon, and flying fish is alibangbang. Our small boat is a tatala, taro is soli, and some call the taro field alibaong."},{en:`When you write Tao, remember the little "’" — it's a glottal stop and a letter of its own, not an accent. ng is one nasal sound, as in mangay "go"; to say n and g apart, write man-gamo. When the stress isn't on the last syllable, books mark it í, á, é, ó.`},{en:`These aren't just "words". Flying fish are a gift from the sea god. How we catch them, cook them and when we stop are all ways of showing respect. To hear more, walk around the fields, the harbour and the health station.`,taoEn:"alibangbang · soli · tagakal  (teaching draft)"}]},clinic_nutrition:{speaker:{en:"Health station nurse"},lines:[{en:"Welcome to the Lanyu Health Station. I can tell you, from a nutrition view, why flying fish and taro are so often on the table together."},{en:"Flying fish (alibangbang) give good protein, omega-3 fats and vitamin D. Taro (soli) gives gentle complex carbs, fibre and potassium. Just right for paddling and field work."},{en:"By tradition, flying fish have their own cooking rules and aren't cooked with certain foods. It's a food custom and an elders' reminder. Nutrition facts add to that custom; they don't replace it.",taoEn:"yakanan no among no rayon  (teaching draft)"}]},taro_intro:{speaker:{en:"Taro field"},lines:[{en:"The terraced water is cool. When the rhythm is right, gently pull up one taro. Only use the teaching field — please don't walk on other people's field banks."}]},fish_rayon:{speaker:{en:"Fisher on the boat beach"},lines:[{en:"It's flying fish season, rayon. This is a timing practice for learning, only at this one spot. The real fishing crews and torches belong to the Tao people. Wait for the moment a flying fish leaps, then go."}]},fish_meyvanwa:{speaker:{en:"Fisher on the boat beach"},lines:[{en:"Tonight and early morning belong to the fish-calling festival, meyvanwa. First learn the names, and learn to wait. Come back in flying fish season for the practice fishing."}]},fish_closed:{speaker:{en:"Fisher on the boat beach"},lines:[{en:"It's not the time to catch flying fish. After the end-of-eating festival, flying fish are no longer eaten, and the off-season uses other kinds of fishing. Respecting the season is respecting the flying fish."}]},jimagaod_look:{speaker:{en:"South coast view"},lines:[{en:"The small island to the south is Little Orchid Island, Jimagaod. Traditionally it's tied to fishing in the Imorod waters and to resources like coconuts. Another day you can go by tatala — for now, put the name in your notebook."}]},harbor_welcome:{speaker:{en:"Kaiyuan Harbour staff"},lines:[{en:"Welcome to Kaiyuan Harbour! Boats depend on the weather. Once the northeast monsoon comes, sailings may stop, so leave an extra day for the trip back."},{en:"The plank boats on the beach belong to each family. Ask before taking photos, and please don't sit in them or touch the boat-eye patterns."}]},visitor_chat:{speaker:{en:"Traveller at Dongqing Bay"},lines:[{en:"I'm recording the beach plants — beach morning glory and crinum lilies grow along the sand. The villagers say to greet people first before going near the underground houses and tagakal pavilions."}]},teacher_idle:{speaker:{en:"Tao language teacher"},lines:[{en:"Want to learn Tao? Come find me at the school any time."}]},rental_idle:{speaker:{en:"Scooter rental owner"},lines:[{en:"Ride slowly. Safety first."}]},shop_idle:{speaker:{en:"Grocery store owner"},lines:[{en:"Come back if you need anything."}]},coach_idle:{speaker:{en:"Dive coach"},lines:[{en:"In flying fish season there's no snorkelling at the village beaches, and no diving at the Yayo drop-off. Come back after the season."}]},weaver_idle:{speaker:{en:"Weaving elder"},lines:[{en:"Watch slowly, learn slowly. I'll teach you the parts that can be shared."}]},recipe_keeper:{lines:[{en:"Want to learn the dishes village families cook at home? Gather the ingredients first, then come to me. I'll teach you step by step."},{en:"Each village and each family does it a bit differently. The details still need checking with the Tao community."}]}}},"/content/dialogue/passersby.json":{dialogues:{dlg_pb_couple:{greet:[{en:"Hi! Are you here on holiday too?"}],idle:[{lines:[{en:"The guesthouse owner said not to touch the boats on the beach, so we take photos from far away."},{en:"The sea at Dongqing Bay is so blue. I could look at it all day."}]},{lines:[{en:"So many stars at night. You never see this in the city."}]}]},dlg_pb_tour:{greet:[{en:"Oh, hello, hello!"}],idle:[{lines:[{en:"Our guide said to keep our voices down in the villages, and to ask before taking photos of people."},{en:"We're going to buy souvenirs later. Do you know where a grocery store is?"}]},{lines:[{en:"A whole day on the tour. My feet are so sore."}]}]},dlg_pb_retiree:{greet:[{en:"Hello, young folks."}],idle:[{lines:[{en:"I'm retired, so I finally have time to walk slowly. The road follows the sea. It's lovely to walk."},{en:"We're not in a hurry. We stop whenever we see something."}]},{lines:[{en:"Early night for me. I want to see the sunrise tomorrow."}]}]},dlg_pb_backpacker:{greet:[{en:"Hi! Hello!"}],idle:[{lines:[{en:"I'm learning Chinese, and a few Tao greetings too."},{en:"I take all my rubbish with me. Rubbish is hard to deal with on an island."}]},{lines:[{en:"I walked so far today. I'll try the other side tomorrow."}]}]},dlg_pb_family:{greet:[{en:"Hello!"}],idle:[{lines:[{en:"It's the kids' first time on Lanyu. They ask about everything."},{en:"Sunscreen, hats, water — we brought it all. The sun is strong by the sea."}]},{lines:[{en:"The kids are worn out. They'll sleep well tonight."}]}]},dlg_kid_tourist_girl:{greet:[{en:"Look! My little bucket!"}],idle:[{lines:[{en:"Mum says the things on the beach are only for looking. We can't take them home."}]}]},dlg_kid_local_ball:{greet:[{en:"Want to play football?"}],idle:[{lines:[{en:"I play football here every day after school."},{en:"Don't kick the ball into anyone's field. Grandma will get angry."}]},{lines:[{en:"It's dark. I'm going home for dinner."}]}]},dlg_kid_quest_tourist:{greet:[{en:"Hello, big brother and sister!"}],idle:[{lines:[{en:"My binoculars can see really far!"}]}],after:{KD1:[{en:"I told Mum and Dad: look at the plank boats from far away, don't touch."}]}},dlg_kid_quest_local:{greet:[{en:"Hello."}],idle:[{lines:[{en:"I like drawing things from the beach — shells, crabs, stones."}]}],after:{KD2:[{en:"I'll take my hermit crab drawing to school to show my teacher."}]}}}},"/content/dialogue/quest-villagers.json":{dialogues:{dlg_villager_iranmeylek:{greet:[{en:"Hey, hello! Here to visit Iranmeylek?"}],duty:[{en:"I run a guesthouse, lead tours, and I'm learning to go to sea with the elders."}],idle:[{lines:[{en:"Dongqing Bay is busiest in the morning. By noon it's quiet."},{en:"On my tours, I always explain the rules first, then the scenery."}]},{lines:[{en:"The bay is nicest at night. The wind blows and you don't have to think about anything."}]},{lines:[{en:"In flying fish season, I remind guests not to go onto the boat beach."}]},{lines:[{en:"Fewer tourists in winter. A good time to fix up the house and spend time with Dad."}]}],after:{"IM-V1":[{en:"The bay is much cleaner. Thank you."}],"IM-V2":[{en:"I said so much that night. Don't laugh at me."}]}},dlg_villager_iratay:{greet:[{en:"Hello! Going to the airport? I can give you a lift if it's on my way."}],duty:[{en:"I run a small business in Iratay and look after the elders at home."}],idle:[{lines:[{en:"The plane is late again. Too windy. People here are used to it."},{en:"Every time Mum goes to Taiwan to see a doctor, I take time off to go with her."}]},{lines:[{en:"The school field is lively at night. The kids are practising songs."}]},{lines:[{en:"Lots of tourists in summer. Business is better, but it's tiring too."}]},{lines:[{en:"Boats often stop in winter, so you have to buy things in advance."}]}],after:{"IT-V1":[{en:"My mum keeps saying how polite you are."}],"IT-V2":[{en:"Don't forget the evening party!"}],NT4:[{en:"Fun party last night, right? The kids sang so well."}]}}}},"/content/dialogue/roles.json":{dialogues:{dlg_clinic_doctor:{greet:[{en:"Hello. Are you feeling unwell?"}],idle:[{lines:[{en:"Check the sea first before going in. If you don't feel well, stay out."},{en:"There's no big hospital on the island. Take care of even small injuries."}]},{lines:[{en:"If something urgent happens at night, call the health station first."}]}]},dlg_nutritionist:{greet:[{en:"Hi! Want to talk about food?"}],idle:[{lines:[{en:"Taro, sweet potato and flying fish together make a very complete meal."},{en:"Instant noodles are handy, but not every day!"}]},{lines:[{en:"Eat something light for dinner and you'll have more energy tomorrow."}]}]},dlg_culture_worker:{greet:[{en:"akokey! Come, sit for a bit."}],idle:[{lines:[{en:'To get to know a village, first learn to ask: "Is this okay?"'},{en:"Some places are sacred. Just look from afar."}]},{lines:[{en:"Village stories at night are only for listening when the elders want to tell them."}]},{lines:[{en:"In flying fish season, visitors should stay off the boat beach."}]}]},dlg_geologist:{greet:[{en:"Oh, hello! Look at this rock —"},{en:"Sorry, I got too excited."}],idle:[{lines:[{en:"Lanyu is a volcanic island. These black rocks are lava from long, long ago."},{en:"The waves cut the rocks into all kinds of shapes, and the Tao people gave them names."}]},{lines:[{en:"At night I sort out my notes from the day."}]}]}}},"/content/gatherNodes/nodes.json":{gatherNodes:[{labelEn:"Dig yams by the hills"},{labelEn:"Pick shellfish on the tide flats"},{labelEn:"Pick seaweed on the tide flats"},{labelEn:"Pick shellfish at dusk low tide (needs a headlamp)",requiresHintEn:"It's getting dark. You need a headlamp to go down to the tide flats."},{labelEn:"Dig sweet potatoes (with permission)",requiresHintEn:"This field belongs to an Iratay family. Help the Iratay woman elder with her harvest and ask her first, then you can dig here."},{labelEn:"Land crabs by the road"},{labelEn:"Hermit crabs at dusk",requiresHintEn:"It's getting dark. You need a headlamp to go down to the tide flats."},{labelEn:"Listen for the scops owl"}]},"/content/glossary.json":{entries:[{en:"Island of People (Lanyu)",categoryEn:"Place",detailEn:`The Tao people's own name for Lanyu, meaning "Island of People". The game uses it as the island's official name.`},{en:"Fish-calling festival",categoryEn:"Festival",detailEn:"The start of the flying fish season (about Feb–Mar). Each boat crew holds a ceremony on the beach to call the flying fish. Also written mivanwa."},{en:"Flying fish season",categoryEn:"Seasons",detailEn:`About Feb–Jun, when flying fish arrive with the Kuroshio current. It's the heart of the yearly cycle of fishing life, not just one "festival".`},{en:"End-of-eating festival",categoryEn:"Festival",detailEn:"Around the Mid-Autumn Festival, the last flying fish ceremony. After it, dried flying fish are no longer eaten, out of respect for the fish."},{en:"Flying fish",categoryEn:"Nature",detailEn:"The Tao word for flying fish. Flying fish are a sacred ceremonial fish, with strict rules for catching and eating them."},{en:"Small plank boat (1–3 people)",categoryEn:"Objects",detailEn:"A plank boat for a family or one person, made of about 21 planks, double-pointed with no outrigger. Please don't touch one without asking."},{en:"Large plank boat (6–10 people)",categoryEn:"Objects",detailEn:"A big boat shared by a fishing crew, usually 6–10 people with three to five pairs of paddles. Night torch fishing in flying fish season is mostly done by big-boat crews."},{en:"Taro",categoryEn:"Food",detailEn:"Taro grown in Lanyu's terraced water fields. A key daily staple and shared in ceremonies, often eaten with dried flying fish."},{en:"Taro field (to be checked)",categoryEn:"Place",detailEn:"Some cultural sources use this word for the taro field."},{en:"Pavilion",categoryEn:"Buildings",detailEn:"A raised pavilion in the village for resting, working and meeting. Take your shoes off before climbing up."},{en:"Little Orchid Island",categoryEn:"Place",detailEn:"The small island south of the main island, tied to the fishing grounds of the Imorod waters."},{en:"Tao language",categoryEn:"Language",detailEn:"The language of the Tao people. This game shows it with Traditional Chinese and romanized spelling."},{en:"Writing notes (Indigenous languages writing system)",categoryEn:"Writing",detailEn:`Following the official writing system for Yami (Tao): "’" is a letter for the glottal stop, not an accent mark. The game always uses the curly ’ (U+2019), never the straight '. ng written together is one nasal sound, as in mangay "go"; when n and g are said apart, add a hyphen, as in man-gamo "tease someone". Stress is usually on the last syllable; when it isn't, textbooks mark í, á, é, ó. Common words: vahay house, among fish, ili village, tao person. (Source: An Introduction to Yami (Tao) Grammar, ch. 2, by D. Victoria Rau and Maa-Neu Dong, Council of Indigenous Peoples, 2018; 2024 revised writing system table)`},{en:"Hello",detailEn:"A greeting. When you meet an elder, say akokey first.",categoryEn:"Language",sourceEn:'ePark Indigenous language site, "Everyday phrases", Yami (provisional)'},{en:"Sea",detailEn:`In the elder's line "ikongo yamyan do wawa?", wawa means the sea.`,categoryEn:"Nature",sourceEn:"ePark Indigenous language site, level 5, lesson 9 (provisional)"},{en:"Crab",detailEn:"The general word for crab. We still need the Tao community to tell us the word for land crabs.",categoryEn:"Food",sourceEn:"ePark Indigenous language site, level 5, lesson 9 (provisional)"},{en:"Pig",detailEn:"Pigs kept beside the family house.",categoryEn:"Nature",sourceEn:"Rau & Dong, Yami Texts with Reference Grammar and Dictionary (provisional)"},{en:"Yayo (village)",categoryEn:"Place",detailEn:"The village on the west coast, next to Kaiyuan Harbour."},{en:"Iraraley (village)",categoryEn:"Place",detailEn:"The village on the north coast."},{en:"Iranmeylek (village)",categoryEn:"Place",detailEn:"The village on the east coast, facing Dongqing Bay."},{en:"Ivalino (village)",categoryEn:"Place",detailEn:"The village on the southeast coast, where traditional houses are best kept."},{en:"Imorod (village)",categoryEn:"Place",detailEn:"The village on the southwest coast, near the health station."},{en:"Iratay (village)",categoryEn:"Place",detailEn:"The village on the west coast, next to the airport."},{en:"Goat",categoryEn:"Nature",detailEn:"Goats are a common sight on the hills and by the road. Each family's goats have the family's own mark on their ears."}]},"/content/items/accessories.json":{items:[{name:{en:"Woven straw hat"},descriptionEn:"A straw hat the Tao woman wove for the traveller from natural, undyed fibre, with a plain fibre band.",codexEn:"An everyday hat with no dye and no pattern. A gift between friends — not traditional clothing, and no ceremonial patterns."},{name:{en:"Small woven pouch"},descriptionEn:"A little pouch the Tao woman wove from natural fibre, hung on a plain twisted cord.",codexEn:"A small undyed woven pouch for coins or pretty stones you find (put them back after looking). An everyday item, not traditional clothing."}]},"/content/items/legacy.json":{items:[{name:{en:"Headlamp"},descriptionEn:"Lights the way at night on the tide flats or back to the village.",codexEn:"A headlamp keeps your hands free. When watching animals at night, keep the light low and don't shine it in their eyes."},{name:{en:"Sunscreen"},descriptionEn:"The island sun is strong. Put some on before swimming or walking the tide flats.",codexEn:"Choose a reef-friendly sunscreen, or wear a long-sleeve sun shirt instead."},{name:{en:"Drinking water"},descriptionEn:"A bottle of water, for you or for busy family members.",codexEn:"Drink water when working in the fields or by the sea. Water is precious on the island — only fill what you'll drink."},{name:{en:"Life jacket"},descriptionEn:"A life jacket borrowed from the scooter rental owner.",codexEn:`Put it on before going into the water or onto a boat. When the sea is rough, Tao people will also say "don't go in today".`},{name:{en:"Flying fish"},descriptionEn:"Flying fish brought back from the sea in flying fish season.",codexEn:"Flying fish are at the heart of Tao culture. How to catch, share, cook them and when to stop all have rules. The game only shows what the Tao community agrees to share.",nutritionEn:"Good protein, omega-3 (EPA/DHA), vitamin D and minerals. An important source of animal protein in the traditional diet."},{name:{en:"Taro"},descriptionEn:"Taro harvested from the taro field.",codexEn:"Taro is the Tao staple food. Women elders lead the planting and care. Fields belong to families — always ask before picking.",nutritionEn:"Complex carbs, fibre, potassium and vitamin B6; resistant starch once cooled. Steady energy for work in the fields and at sea."},{name:{en:"Sweet potato"},descriptionEn:"Sweet potato. Filling and keeps well.",codexEn:"Sweet potatoes grow in dry fields and are the other main staple besides taro. Travellers usually buy them at the grocery store. The Tao name is provisional and still needs checking with the community.",nutritionEn:"Sweet potato gives starch, fibre, potassium and beta-carotene (more in yellow and orange kinds). A filling staple that keeps well. The Tao name wakay is provisional and still needs checking with the community."},{name:{en:"Yam"},descriptionEn:"A yam dug up by the hills.",codexEn:"Yam is smooth and easy to digest. Where and when to dig still needs checking with the community; the Tao name is provisional.",nutritionEn:"Yam has starch, mucilage and potassium. Smooth and easy to digest. The Tao name ovi is provisional (weak source) and still needs checking with the community."},{name:{en:"Shellfish"},descriptionEn:"Shellfish picked on the tide flats at low tide.",codexEn:"Leave the small ones and only take what you need. Each village has its own rules on what to pick and when.",nutritionEn:"Protein, iron, zinc and vitamin B12. The Tao name still needs checking with the community."},{name:{en:"Seaweed"},descriptionEn:"Seaweed picked on the tide flats.",codexEn:"Picked on the rocks at low tide. Seaweed has iodine and minerals and is often eaten with taro or sweet potato. The Tao name still needs checking with the community.",nutritionEn:"Iodine, calcium and other minerals, plus fibre. The Tao name still needs checking with the community."},{name:{en:"Coconut"},descriptionEn:"The coconuts mentioned while looking from Imorod toward Little Orchid Island.",codexEn:"Tao people often mention coconuts together with Little Orchid Island. In the game you only look, not pick.",nutritionEn:"Coconut flesh gives medium-chain fats and fibre; coconut water has electrolytes. Coconuts are often mentioned together with Little Orchid Island."}]},"/content/items/observations.json":{items:[{name:{en:"Land crab"},descriptionEn:"Land crabs crossing the road on summer nights.",codexEn:"On summer nights, land crabs go down to the sea to release their young. Slow down on the road, don't catch them or block their way — just count them."},{name:{en:"Hermit crab"},descriptionEn:"Hermit crabs carrying their shells across the tide flats at night.",codexEn:"Hermit crabs need the right shells to grow. Don't take shells home as souvenirs."},{name:{en:"Lanyu scops owl"},descriptionEn:"The Lanyu scops owl calling in the roadside woods at night.",codexEn:"A small owl found only on Lanyu. When watching, no flash and no recorded calls to lure it. The Tao people have their own views on owls — please respect them."},{name:{en:"Goat"},descriptionEn:"Goats on the slopes of Imorod.",codexEn:"The island's goats belong to families. The mark on the ear shows which family. Don't touch goats that aren't yours."}]},"/content/items/village-crafts.json":{items:[{name:{en:"Millet"},descriptionEn:"A small handful of millet from the Iraraley woman elder.",codexEn:"Millet is one of the island's old crops, and women elders look after the fields. The planting and harvest times and related rules still need checking with the community; the Tao name is unconfirmed."},{name:{en:"Taro shoots"},descriptionEn:"Taro shoots ready for replanting.",codexEn:"After harvest, keep the top of the taro stem and plant it back, and the field can go on and on."},{name:{en:"Taro and sweet potato lunch"},descriptionEn:"A packed lunch from the Iraraley woman elder, for the people working up the mountain.",codexEn:"What the family eats and takes up the mountain is planned by the women elders. Just drop it near the work site — don't go into the place where the men are working."},{name:{en:"Ramie thread"},descriptionEn:"Ramie thread wound by the Tao woman.",codexEn:"Ramie is stripped, soaked and dried, then twisted into thread and wound into balls for weaving. Women don't weave in flying fish season, so this is mostly done in winter."},{name:{en:"Cotton thread"},descriptionEn:"A bundle of coloured cotton thread from the Yayo grocery store.",codexEn:"Modern cotton thread you can buy. Handy for sewing small everyday things."},{name:{en:"Cloth scraps"},descriptionEn:"Leftover cloth edges from the weaving elder.",codexEn:"Leftover edges from weaving are too good to throw away and can be sewn into small things. Keep them plain and simple — don't copy ceremonial patterns."}]},"/content/meta.json":{roles:{m:{en:"Tao man",iconEn:"M"},f:{en:"Tao woman",iconEn:"W"},t:{en:"Traveller",iconEn:"T"}},respect:[{en:"First visit"},{en:"Learning"},{en:"Trusted"},{en:"Friend"}],seasons:{summer:{en:"Summer · Flying fish season"},winter:{en:"Winter · Northeast monsoon"}},externalProgress:{respectEn:"Respect points build up from game events (Q04 = first, V1 = learning; trusted / friend come from respect events)",countEn:"Counters (photos, lowTideOnTime…) build up from game events"},giverLabels:{fEn:"Given and checked by a woman elder",mEn:"Given and checked by a man elder"}},"/content/milestones.json":{milestones:[{en:"Set foot on Pongso no Tao",detailEn:"Choose your home and walk into Lanyu."},{en:"Put the island's name in your notebook",detailEn:"Ask an elder and unlock your first Tao word cards."},{en:"Health station notes",detailEn:"At the Imorod health station, note how flying fish and taro work together as food."},{en:"First taro harvest",detailEn:"Harvest taro once in the teaching field."},{en:"The sea in flying fish season",detailEn:"Do the timing activity once at the practice spot during flying fish season."},{en:"A view of Little Orchid Island",detailEn:"Look out at Jimagaod from the south coast and add it to your coconut notes."},{en:"Four lights of the island",detailEn:"See dawn, day, dusk and night for yourself."},{en:"A full year",detailEn:"Experience the fish-calling festival, flying fish season, end-of-eating festival and the off-season."}]},"/content/npcs/cast.json":{npcs:[{name:{en:"Imorod elder"},dutyTextEn:"The mountain (goat herding) and forest"},{name:{en:"Ivalino elder"},dutyTextEn:"Flying fish season rules and sharing the catch"},{name:{en:"Yayo elder"},dutyTextEn:"Going to sea in flying fish season, nets and fishing crews"},{name:{en:"Health station nurse"}},{name:{en:"Taro field elder"},dutyTextEn:"Taro field"},{name:{en:"Plank boat fisher"}},{name:{en:"Iranmeylek villager"}},{name:{en:"Iratay villager"}},{name:{en:"Visitor just off the plane"}},{name:{en:"Traveller at Dongqing Bay"}},{name:{en:"Kaiyuan Harbour staff"}},{name:{en:"Iraraley elder"},dutyTextEn:"Building plank boats and choosing trees on the mountain"},{name:{en:"Iranmeylek elder"},dutyTextEn:"Plank boats at sea, ropes and paddling"},{name:{en:"Iratay elder"},dutyTextEn:"Going to sea and sharing fish in flying fish season"},{name:{en:"Tao language teacher"}},{name:{en:"Scooter rental owner"}},{name:{en:"Grocery store owner"}},{name:{en:"Dive coach"}},{name:{en:"Weaving elder"},dutyTextEn:"Weaving"},{name:{en:"Health station doctor"}},{name:{en:"Dietitian"}},{name:{en:"Village culture worker"}},{name:{en:"Geologist"}},{name:{en:"Yayo villager"}},{name:{en:"Yayo youth"}},{name:{en:"Yayo child"}},{name:{en:"Iraraley villager"}},{name:{en:"Iraraley youth"}},{name:{en:"Iraraley child"}},{name:{en:"Iranmeylek youth"}},{name:{en:"Iranmeylek child"}},{name:{en:"Ivalino villager"}},{name:{en:"Ivalino youth"}},{name:{en:"Ivalino child"}},{name:{en:"Imorod villager"}},{name:{en:"Imorod youth"}},{name:{en:"Imorod child"}},{name:{en:"Iratay youth"}},{name:{en:"Iratay child"}},{name:{en:"Yayo woman elder"},dutyTextEn:"Food: cooking and storing"},{name:{en:"Iraraley woman elder"},dutyTextEn:"Fields: yams and millet"},{name:{en:"Iranmeylek woman elder"},dutyTextEn:"Tide flat gathering and cooking"},{name:{en:"Iratay woman elder"},dutyTextEn:"Fields: sweet potato and taro"}]},"/content/npcs/passersby.json":{npcs:[{name:{en:"Couple on holiday"}},{name:{en:"Couple on holiday"}},{name:{en:"Tour group traveller"}},{name:{en:"Woman traveller"}},{name:{en:"Retired traveller"}},{name:{en:"Retired traveller"}},{name:{en:"Backpacker"}},{name:{en:"Dad on a family trip"}},{name:{en:"Mum on a family trip"}},{name:{en:"Young visitor · Girl"}},{name:{en:"Curious young visitor"}},{name:{en:"Village girl who loves drawing"}},{name:{en:"Village boy playing football"}}]},"/content/outfits/outfits.json":{outfits:[{name:{en:"Tao man's traditional clothing"},excludesEn:["Silver helmet","Gold plates","Ceremonial items"]},{name:{en:"Tao woman's traditional clothing"},excludesEn:["Ceremonial items"]},{name:{en:"Woven straw hat"}},{name:{en:"Small woven pouch"}}]},"/content/photoSpots/legacy.json":{photoSpots:[{name:{en:"Hongtou Rock"},snap:[{en:"📸 The road goes right through the rock. Gotta keep this one."},{en:"📸 Hongtou Rock, got it! I'll come back at dusk to see it turn red."},{en:"📸 The sea's right outside the tunnel. The shot basically framed itself."}]},{name:{en:"Carp Rock"},snap:[{en:"📸 Carp Rock! Look, it really does kind of look like a jumping fish."},{en:"📸 Okay, this fish is in the album now."}]},{name:{en:"Tank Rock"},snap:[{en:"📸 Tank Rock, barrel pointed at the sea. Pretty impressive."},{en:"📸 Got it. The name's from the maps. Let's ask what the Tao call it."}]},{name:{en:"View from Lanyu Lighthouse"},snap:[{en:"📸 From the lighthouse, the whole sea is blue."},{en:"📸 So windy. Steady hands… okay, got it!"},{en:"📸 The island looks totally different from up here."}]},{name:{en:"Five Holes Cave (photos from outside only)"},snap:[{en:"📸 We'll just shoot the Five Holes Cave from outside. No need to go in and disturb it."},{en:"📸 One shot from afar is enough. Let the place stay quiet."}]},{name:{en:"Jade Maiden Rock"},snap:[{en:"📸 Jade Maiden Rock, standing quietly by the sea."},{en:"📸 Into the album. The light's just right. Lucky."}]},{name:{en:"Little Heaven Lake (from afar only)"},snap:[{en:"📸 We'll keep Little Heaven Lake at a distance. It's a place to respect."},{en:"📸 One from afar. The water's like a mirror."}]},{name:{en:"Hen Rock"},snap:[{en:"📸 Hen Rock! It really looks like a hen sitting on eggs."},{en:"📸 Done. I hear the water down there is great for snorkelling."}]},{name:{en:"Stars over Twin Lions Rock"},snap:[{en:"📸 Stars all over Twin Lions Rock… gotta keep the shutter open longer."},{en:"📸 You just can't see stars like this in the city."},{en:"📸 Everybody hold still… okay, got it!"}]},{name:{en:"Battleship Rock from the shore"},snap:[{en:"📸 We'll shoot Battleship Rock from the shore. It's too far out by boat."},{en:"📸 From here it really looks like a ship parked at sea."}]},{name:{en:"Lovers' Cave"},snap:[{en:"📸 Lovers' Cave, with the waves rolling right in."},{en:"📸 Got it. The rocks are slippery, careful everyone."}]},{name:{en:"Sky Crack"},snap:[{en:"📸 Sky Crack! Look up and there's just a sliver of sky."},{en:"📸 The cliffs are so close. Feels intense in the shot."}]},{name:{en:"Sunrise at Dongqing Bay"},snap:[{en:"📸 Sunrise at Dongqing Bay. Totally worth getting up early!"},{en:"📸 Caught the second the sun came up out of the sea."},{en:"📸 Wait, one more… okay, this one's the best."}]},{name:{en:"Helmet Rock"},snap:[{en:"📸 Helmet Rock. Like someone left a helmet by the sea."},{en:"📸 Got it! Such a cute round rock."}]},{name:{en:"Elephant Trunk Rock"},snap:[{en:"📸 Elephant Trunk Rock, its trunk dipping right into the sea."},{en:"📸 From the right angle, it really is an elephant."}]},{name:{en:"Lanyu Waterfall"},snap:[{en:"📸 Lanyu Waterfall. So loud, so cool."},{en:"📸 Got it. The camera's a bit wet. Worth it."}]},{name:{en:"Dragon Head Rock"},snap:[{en:"📸 Dragon Head Rock. Looks like it could swim off any second."},{en:"📸 Okay, the dragon's head is in the album."}]},{name:{en:"Big Heaven Lake (from afar only)"},snap:[{en:"📸 Just one of Big Heaven Lake from afar. We won't go closer."},{en:"📸 A pool of water ringed by mountains. So peaceful."}]},{name:{en:"Old Man Rock"},snap:[{en:"📸 Old Man Rock, like someone sitting and watching the sea."},{en:"📸 Got it. He's probably been watching for a long time."}]},{name:{en:"Dusk on Qingqing Prairie"},snap:[{en:"📸 Dusk on Qingqing Prairie. The whole field's gone gold."},{en:"📸 The breeze feels so nice… okay, got it."},{en:"📸 This one's going to be my wallpaper."}]},{name:{en:"Badai Bay (in flying fish season, only from outside the village)"},snap:[{en:"📸 We'll shoot Badai Bay from outside the village. Don't want to bother anyone."},{en:"📸 One from afar. The bay's beautiful."}]},{name:{en:"Mantou Rock"},snap:[{en:"📸 Mantou Rock, round like a steamed bun. Now I'm hungry."},{en:"📸 Done! Let's go grab something to eat."}]},{name:{en:"Kaiyuan Harbour"},snap:[{en:"📸 Kaiyuan Harbour, where we landed."},{en:"📸 Boats coming and going, so lively. One for the memories."}]},{name:{en:"Lanyu Airport (scenery only)"},snap:[{en:"📸 Just the scenery at the airport. Such a tiny runway."},{en:"📸 Okay, got it. Next time we fly in, this is where we land."}]},{name:{en:"View down from the Lanyu Weather Station"},snap:[{en:"📸 From the weather station, half the island is at your feet."},{en:"📸 Tiring climb, but this shot's worth it!"}]},{name:{en:"Ivalino traditional houses (ask the owner first)"},snap:[{en:"📸 The owner said it's okay, so we'll get the houses from a bit further back."},{en:"📸 Thanks to the owner. The houses sit low against the ground. Such clever design."}]},{name:{en:"Plank boats at Iraraley Bay (ask the owner first)"},snap:[{en:"📸 The boat owner said yes. We'll shoot from afar and not touch the boats."},{en:"📸 Thanks to the owner. The plank boats in the bay look beautiful."}]},{name:{en:"Snorkelling at Hen Rock"}},{name:{en:"Yayo Harbour drop-off: a shallow scuba dive with the dive coach"}},{name:{en:"Hidden: the traveller's underwater view"}}]},"/content/photoSpots/new.json":{photoSpots:[{name:{en:"Night lights at Kaiyuan Harbour"},snap:[{en:"📸 The night lights at Kaiyuan Harbour, wobbling in the water."},{en:"📸 The harbour's so quiet at night. Got it."}]},{name:{en:"Moonrise at Dongqing Bay"},snap:[{en:"📸 The moon's up over Dongqing Bay. A bright path across the sea."},{en:"📸 Got it. Sunrise this morning, moonrise tonight. What a deal."}]},{name:{en:"Northeast monsoon waves"},snap:[{en:"📸 The monsoon waves are huge. Let's shoot from further back."},{en:"📸 The waves crashing in are wild. Got it, back up, back up."}]},{name:{en:"Lanyu scops owl by the road"},snap:[{en:"📸 There's the scops owl… no flash, keep it down."},{en:"📸 Got it. I think it looked at me. Let's go and leave it be."}]}]},"/content/phrases.json":{phrases:{ikongo:{en:"What's in the sea?",sourceEn:"ePark Indigenous language site, level 5, lesson 9 (provisional)"},mangay:{en:"I'll go and look first.",sourceEn:"ePark Indigenous language site, level 7, lesson 7 (provisional)"}}},"/content/places.json":{places:{yayo:{en:"Yayo",flavorEn:"A lively west-coast village, home to Kaiyuan Harbour and the shops. Yayo means a place with plenty of food."},iraraley:{en:"Iraraley",flavorEn:'The north-coast village with the widest land, an upper and a lower settlement and broad tide flats. Iraraley means "polite".'},iranmeylek:{en:"Iranmeylek",flavorEn:"On Dongqing Bay on the north-east coast, where the island sees the first light of the day."},ivalino:{en:"Ivalino",flavorEn:"On the south-east coast, the village with the best-kept traditional underground houses. Ivalino is linked to the beach morning glory."},imorod:{en:"Imorod",flavorEn:"On the south / south-west coast, where the flying fish story began; the health station, the post office and Badai Bay are around here."},iratay:{en:"Iratay",flavorEn:"A flat, open place on the south-west coast, where Lanyu Airport is. It has the least land."},harbor:{en:"Kaiyuan Harbour",flavorEn:"The main harbour for people and goods, in Yayo; boats from Fugang in Taitung and from Houbihu stop here."},clinic:{en:"Lanyu Health Station",flavorEn:"The only health station on the island, in Imorod. In the game it is where traditional food and modern nutrition meet."},airport:{en:"Lanyu Airport",flavorEn:"The island's airport, in Iratay."},jimagaod:{en:"Little Orchid Island",flavorEn:"A small island south of the main island, traditionally linked to the Imorod waters, fishing and hunting, and coconuts. In this early version you look at it from afar."},taro_yayo:{en:"Yayo taro field"},taro_iraraley:{en:"Iraraley taro field"},taro_iranmeylek:{en:"Iranmeylek taro field"},taro_ivalino:{en:"Ivalino taro field"},taro_imorod:{en:"Imorod taro field"},taro_iratay:{en:"Iratay taro field"},fishzone_west:{en:"West coast flying fish waters"},fishzone_east:{en:"Open sea off Dongqing Bay"},peak:{en:"Around Mt. Hongtou"},iranmeylek_beach:{en:"Dongqing Bay beach"},iratay_shore:{en:"Iratay boat beach"},iratay_school:{en:"Iratay school playground"},wakay_iratay:{en:"Iratay sweet potato field"},owl_road:{en:"Roadside woods on the west coast"},five_caves_view:{en:"Five Holes Cave (seen from the road)"},small_lake_view:{en:"Little Heaven Lake (seen from afar)"},big_lake_view:{en:"Big Heaven Lake (seen from afar)"},badai_view:{en:"Badai Bay lookout"},hutou_slope:{en:"Hutou Slope"},thatch_field:{en:"Thatch grass on the hillside"}}},"/content/quests/kids.json":{quests:[{name:{en:"The young visitor's binoculars"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year (day)",preEn:"Q07 (Island rules)",unlockEn:"A promise with the young visitor",kindEn:"Short story"},steps:[{textEn:"Talk with the young visitor in Iranmeylek",lines:[{en:"I saw a really pretty boat on the beach with my binoculars! Can I sit in it for a photo?"},{en:"That's a Tao family's plank boat. You can't just touch it or sit in it. Let's go look from far away together."}]},{textEn:"Go to the beach at Dongqing Bay and look at the plank boats from far away",lines:[{en:"The plank boats on the beach are made by a family and a boat crew together. Looking from afar, not going near and not touching is how you respect the boat and its owners."},{en:"Binoculars are enough. You can see even the patterns on the boat clearly."}]},{textEn:"Go back and tell the young visitor",lines:[{en:"Got it! I'll only look with my binoculars and won't touch. I'll tell Mum and Dad too."}],gives:{toastEn:["The young visitor's binoculars","You enjoyed the plank boats from afar with the young visitor."]}}],hint:{fromEn:"Iranmeylek",en:"There's a young visitor with binoculars in Iranmeylek who seems curious about the boats on the beach."}},{name:{en:"The girl who loves drawing"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year (at low tide: dawn or dusk)",preEn:"Q07 (Island rules)",unlockEn:"The girl's hermit crab drawing",kindEn:"Short story"},steps:[{textEn:"Talk with the girl who loves drawing, next to the Iratay school",lines:[{en:"I'm drawing things from the beach. But hermit crabs often live in the shells, and I don't want to take them away."},{en:"At low tide, could you come with me to the beach?"}]},{textEn:"At low tide, go to the Iratay beach and watch hermit crabs with the girl",lines:[{en:"Look but don't take: an empty shell may be a hermit crab's home, and put any stones you turn back where they were."},{en:"Found one! It's walking slowly with its shell. We'll just watch."}]},{textEn:"Go back and see the girl's drawing",lines:[{en:"I drew it in my book! And it's still where it was. That's nice."}],gives:{toastEn:["The girl who loves drawing","The girl drew the hermit crab in her book."]}}],hint:{fromEn:"Iratay",en:"There's a girl with a sketchbook next to the Iratay school. She wants to draw hermit crabs."}}]},"/content/quests/language.json":{quests:[{name:{en:"Find the Tao language teacher at the Yayo school"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Notebook Tao word cards, X02, X03"},steps:[{textEn:"Go to the Yayo school in the daytime to find the Tao language teacher",lines:[{en:"Hello. I teach Tao at the school here."},{en:"If you hear the elders speak Tao and don't understand, write it down and bring it to me. Words you learn go onto the Tao word cards in your notebook."}],gives:{toastEn:["Tao word cards",'You can start collecting "Tao word cards" in your notebook.']}}],hint:{fromEn:"Scooter rental owner",en:"The Tao language teacher is at the Yayo school in the daytime."}},{name:{en:"First phrase: akokey (hello)"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"1 Tao word card, greeting hints from NPCs"},steps:[{textEn:"Learn your first phrase from the Tao language teacher: akokey (hello)",lines:[{en:"The first thing to learn is a greeting."},{en:"Say akokey when you meet an elder — it makes everyone happy."}]}],hint:{fromEn:"Tao language teacher",en:"Talk to the Tao language teacher again to learn your first phrase."}},{name:{en:"Take an elder's Tao hint to the teacher"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year (day)",preEn:"X01 and the first hint given only in Tao",unlockEn:"Translation, X04, Z1",kindEn:"AND + Tao hint"},steps:[{textEn:"Take the elder's Tao-only hint to the Tao language teacher to translate",lines:[{en:"An elder spoke to you in Tao? Let me check my notes."}],gives:{toastEn:["Translation","From now on, bring any Tao-only hints to the teacher to translate."]}}],hint:{fromEn:"Tao language teacher",en:"When an elder gives you a hint only in Tao, take it back to the Yayo school for the teacher to translate."}},{name:{en:"Collect 10 Tao word cards"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",kindEn:"Count 10"},steps:[{textEn:"Collect 10 Tao word cards"}],hint:{fromEn:"Tao language teacher",en:"Talk with elders and villagers more. Words you learn are added to your Tao word cards automatically."}},{name:{en:"Collect 20 Tao word cards"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Hidden quest H1",kindEn:"Count 20"},steps:[{textEn:"Collect 20 Tao word cards"},{textEn:"Show your 20 word cards to the Tao language teacher",lines:[{en:"Twenty words! You already know more than many kids."},{en:"From here on, the best teachers are the elders in the villages."}],gives:{toastEn:["Tao word cards","You've collected 20 Tao words."]}}],hint:{fromEn:"Tao language teacher",en:"Talk with elders and villagers and visit every village. Words you learn are added to your Tao word cards automatically."}}]},"/content/quests/later.json":{quests:[{name:{en:'Get the food store "just right" before the flying fish season ends'},text:{whoEn:"Whole party",coopEn:"No need to be there together",seasonEn:"End of flying fish season",preEn:"G1 and G2",unlockEn:'Milestone "Just right"'},steps:[{textEn:"Ask the host family's woman elder to check the food store",lines:[{en:"The dried flying fish and taro are all in. Let's count."},{en:"Enough to last until the flying fish season ends — not too much, not too little. Just right is best."},{en:`"Just right": no waste, nothing missing. Extra goes to relatives; if we're short, everyone helps.`}],gives:{toastEn:['Milestone "Just right"','The food store is "just right" before the flying fish season ends.']}}],hint:{fromEn:"Host family",en:"The dried flying fish and taro are stored. Ask the host family's woman elder to check the food store."}},{name:{en:"Share taro with three related families"},text:{whoEn:"Tao man, Tao woman",coopEn:"Solo",seasonEn:"All year",preEn:"R4 or G1",unlockEn:"Village ties"},steps:[{textEn:"The host family's woman elder asks: share taro with three related families",lines:[{en:"The field gave well this year. Pick three taro and take them to three relatives' homes."},{en:"When you give them, say it's from our family. They'll understand."}]},{textEn:"Pick three taro in the family's taro field",lines:[{en:"Pick the big ones, one per family."}]},{textEn:"Take a taro to the relatives in Yayo",lines:[{en:"From the host family? Please thank her for me."}],alt:{textEn:"Take a taro to the relatives in Iranmeylek",lines:[{en:"From the host family? Please thank her for me."}]}},{textEn:"Take a taro to the relatives in Iraraley",lines:[{en:"This year's taro is great. Next time we'll bring some to you."}],alt:{textEn:"Take a taro to the relatives in Iratay",lines:[{en:"This year's taro is great. Next time we'll bring some to you."}]}},{textEn:"Take a taro to the relatives in Ivalino",lines:[{en:"Got it. Food from the fields tastes best when everyone shares it."}],alt:{textEn:"Take a taro to the relatives in Imorod",lines:[{en:"Got it. Food from the fields tastes best when everyone shares it."}]}},{textEn:"Report back to the host family",lines:[{en:"All delivered? Good. That's how it is between relatives — give and take."}],gives:{toastEn:["Village ties","All three related families received taro from the host family."]}}],hint:{fromEn:"Host family",en:"After the harvest, the host family's woman elder will ask you to share taro with relatives."}},{name:{en:"Mend a fishing net with the Tao man"},text:{whoEn:"Traveller (more content for a male traveller)",coopEn:"Pair: Traveller + Tao man",seasonEn:"All year",unlockEn:"Advanced net-knotting card"},steps:[{textEn:"The traveller and the Tao man go to Kaiyuan Harbour and ask the plank boat fisher if any nets need mending",lines:[{en:"This net has quite a few holes. Good timing."},{en:"The Tao man mends the big holes, the traveller the small ones. Tie the knots the way you learned."}]},{textEn:"Mend the net together by the harbour",lines:[{en:"First trim the broken ends, then mend it back one square at a time."},{en:"These knots are much tighter than last time!"}]},{textEn:"Hand back the mended net",lines:[{en:"Nice work. With the net mended, the boat crew can use it next time they go out."}],gives:{toastEn:["Advanced net-knotting card","The traveller and the Tao man mended a fishing net together."]}}],hint:{fromEn:"Kaiyuan Harbour",en:"After learning to knot nets, you can go with the Tao man to Kaiyuan Harbour and help the plank boat fisher mend nets."}},{name:{en:"Show 10 field guide cards to the Tao language teacher"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Food words added to the Tao word cards",kindEn:"Count 10"},steps:[{textEn:"Bring the field guide cards to the Tao language teacher",lines:[{en:"You brought your field guide cards? Let's see together which things have Tao names."},{en:"If we're not sure of a Tao name, leave it blank until the community tells us. Don't guess."}]},{textEn:"At the school, lay the ten cards on the table and match them one by one",lines:[{en:"Taro is soli, flying fish is alibangbang, crab is kalang."}]},{textEn:"Listen to the teacher explain the food words",lines:[{en:"Once you can name a food, you'll want to know where it comes from. Next time, bring what the elders say."}],gives:{toastEn:["Tao word cards","Food words were added to the Tao word cards."]}}],hint:{fromEn:"Tao language teacher",en:"The Tao language teacher wants to see the field guide cards you've collected. Take them to the Yayo school."}},{name:{en:"Count the land crabs by the road and report back (no catching)"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"Land crab season, at night",unlockEn:"Nature points, land crab care card"},steps:[{textEn:"Count land crabs by the road at night (look only — no catching, no bright lights)",lines:[{en:"One, two, three… seven on this stretch of road."},{en:"Use a red or dim light. Don't catch them or block their way."}]},{textEn:"Go home and tell the elder how many you counted",lines:[{en:"Seven, eh? They take the same path every year. We just make way for them."}],gives:{toastEn:["Land crab care card","Nature points up."]}}],hint:{fromEn:"Villager",en:"On land crab season nights, crabs often cross the west coast road. Just count them."}},{name:{en:"Hidden: record an elder's words for the Tao language teacher (ask first)"},text:{whoEn:"Traveller + any Tao member",coopEn:"Pair: Traveller + Tao member",seasonEn:"All year",unlockEn:"Elder's story card",kindEn:"Hidden"},steps:[{textEn:"On the pavilion, the traveller and a Tao member first ask the elder if it's okay to record",lines:[{en:"Could we record a few of your words for the Tao language teacher? Only for teaching Tao at school."},{en:"Record what?"},{en:"Just a greeting. If you'd rather not, we won't record."},{en:"A greeting is fine. The stories — let me think. Some aren't for everyone to hear."},0]},{textEn:"Give the recording to the Tao language teacher",lines:[{en:"Thank you for asking the elder first. I'll keep the recording safe and only use it in class."}],gives:{toastEn:["Elder's story card","The elder agreed to record a greeting. The stories can wait until the elder wants to tell them."]}}],hint:{fromEn:"Tao language teacher",en:"The Tao language teacher says it would be great to hear Tao from an elder's own voice… but always ask first."}},{name:{en:"Hidden: the dietitian's little food survey"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",preEn:"First meeting with the dietitian",unlockEn:"Nutrition and health card",kindEn:"Hidden: first meeting"},steps:[{textEn:"The dietitian asks everyone to note what they eat for a week. Ask the host family first",lines:[{en:"What do we eat in a week? Taro, sweet potato, fish, and some noodles. When we're busy, we eat something quick."}]},{textEn:"Give the week's food notes to the dietitian",lines:[{en:"Taro, sweet potato, fish and seaweed, plus some noodles and rice — that's the table in many island homes today."},{en:"Traditional food is already well balanced. A bit less instant noodles, a bit more from the fields and the sea, and you're good."}],gives:{toastEn:["Nutrition and health card","The dietitian's food survey is done."]}}],hint:{fromEn:"Health station",en:"The dietitian seems to be looking for help with a food survey."}},{name:{en:"Hidden: tide pool watching (look, don't pick)"},text:{whoEn:"Tao woman + Traveller",coopEn:"Pair: Tao woman + Traveller",seasonEn:"At low tide",preEn:'Achievement "On time for low tide" ×3',unlockEn:"Nature points, tide pool card",kindEn:"Hidden + tide"},steps:[{textEn:"At low tide, the Tao woman shows the traveller the tide pools (look, don't pick)",lines:[{en:"Crouch down to look. After turning a stone, put it back where it was."},{en:"There are starfish, little fish and hermit crabs. I'll just take photos, not take anything."}],gives:{toastEn:["Tide pool card","Looked without picking. Nature points up."]}}],hint:{fromEn:"Iranmeylek",en:"People who often reach the shore right at low tide will find lots of life in the tide pools."}},{name:{en:"Hidden: a small island photo show at the school"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year",preEn:"Any 6 album photos (collection goal)",unlockEn:"Village ties, place names added to Tao word cards",kindEn:"Hidden: collection goal"},steps:[{textEn:"The Tao language teacher wants to hold a small photo show at the school",lines:[{en:"You've taken so many photos of the island. Could the school borrow them for a little show?"},{en:"Write the place name on each photo, and the rule you kept when you took it."}]},{textEn:"Put up the photos one by one at the school",lines:[{en:"This one I only took from the roadside; for this one I asked the owner first."},{en:"The kids gather round, pointing at the photos and naming the villages."}]},{textEn:"Show finished",lines:[{en:"The kids say they didn't know outsiders saw our island like this. Thank you."}],gives:{toastEn:["Island photo show","Place names added to the Tao word cards. Village ties up."]}}],hint:{fromEn:"Tao language teacher",en:"The Tao language teacher heard the traveller took lots of photos."}},{name:{en:"The culture worker tells stories of coastal place names (content to be confirmed)"},text:{whoEn:"Traveller",coopEn:"Solo (NPC culture worker)",seasonEn:"All year",preEn:'B1 and the album set "North coast rocks"',unlockEn:"Story card (from the community), place names added to Tao word cards",kindEn:"AND + collection goal"},steps:[{textEn:"The traveller brings the photos and hears the culture worker talk about coastal place names",lines:[{en:"All these — this rock, that cave — many of the names were given by outsiders, based on shapes."},{en:"The Tao people have their own name for every cape and every reef — some remember who landed there, or who once dried clothes there."},{en:"In recent years, the village's young people have been bringing the names and stories back, one rock at a time."},{en:"Names and stories should be told by the village itself. When the community agrees, I'll tell you one by one."},{en:"I'll leave a space in the album for the community to fill in."}],gives:{toastEn:["Story card (from the community)",'Album photos now have a "Tao place name" space, waiting for the community.']}}],hint:{fromEn:"Iraraley",en:"After you photograph the north coast rocks, the village culture worker wants to talk with the traveller about the names of these places."}},{name:{en:"Find the geologist doing fieldwork (❗ moves around)"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"Day",unlockEn:"Geology notes in the album, rock field guide, D2",kindEn:"A moving ❗"},steps:[{textEn:"Find the geologist doing fieldwork",lines:[{en:"You found me! I'm studying the coastal rocks, and I'm somewhere new every day."},{en:"Want to look together? I can show you how to read rocks."}],gives:{toastEn:["Geology notes","Album photos now have a geology notes space."]}}],hint:{fromEn:"Villager",en:"A geologist with a magnifying glass runs all over the island. Who knows where today."}},{name:{en:"See the volcanic coast with the geologist"},text:{whoEn:"Anyone",coopEn:"Solo (NPC geologist)",seasonEn:"Day",unlockEn:"Volcano and rock card, D3"},steps:[{textEn:"Arrange with the geologist to see the volcanic coast",lines:[{en:"Let's go to that big rock on the northwest coast. It's the best one."}]},{textEn:"See the volcanic coast with the geologist",lines:[{en:"These blocks are piled-up debris from eruptions. The hard parts stay; the soft parts are carried off by the waves."},{en:"That's the geology view. The Tao people have their own name and story for this rock. Both are worth hearing."}],gives:{toastEn:["Volcano and rock card","Lanyu was formed by an undersea volcano."]}}],hint:{fromEn:"Geologist",en:"The geologist wants to take everyone to see the volcanic coast."}},{name:{en:"Watch sea-carved landforms from the trail and roadside"},text:{whoEn:"Anyone",coopEn:"Solo (NPC geologist)",seasonEn:"Day, safer at low tide",preEn:'D2 and the album set "East coast"',unlockEn:"Sea erosion card, the geologist's hidden field notes",kindEn:"AND + collection goal"},steps:[{textEn:"Look at a sea arch from the roadside",lines:[{en:"Year after year the waves hit the cracks in the rock. The cracks grow until a hole goes right through — an arch."},{en:"All the rocks you've photographed were slowly carved by the sea like this. Just look from the road — the cliff edge is dangerous."}]},{textEn:"The geologist takes out his field notes",lines:[{en:"This is my field record. You can copy it. Remember — always ask the Tao people for the names."}],gives:{toastEn:["Sea erosion card","You got the geologist's hidden field notes."]}}],hint:{fromEn:"Geologist",en:"After you photograph the east coast rocks, the geologist wants to show everyone the sea-carved landforms."}},{name:{en:"Hidden: the traveller's underwater view"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"Same as U1",preEn:"The traveller finishes U1",unlockEn:"Traveller's underwater photo set (3 photos, just to keep)",kindEn:"Hidden: the traveller finishes U1"},steps:[{textEn:"The traveller takes a camera snorkelling at Hen Rock again for a set of underwater photos",lines:[{en:"This time I'll take the photos. I want to keep the coral and the schools of fish."}],gives:{toastEn:["Traveller's underwater photos",'3 photos added to "Album & underwater".']}}],hint:{fromEn:"Traveller",en:"Take a camera when you snorkel. You could get some very different shots."}}]},"/content/quests/main-flyingfish.json":{quests:[{name:{en:"Prepare the plank boat and fishing gear"},text:{whoEn:"Tao man",coopEn:"Solo (with an NPC boat crew)",seasonEn:"Late in the wait for flying fish season"},steps:[{textEn:"The Tao man takes a job from the man elder: prepare the plank boat and fishing gear",lines:[{en:"Flying fish season is coming. The boat and gear need sorting first. Go with the boat crew to the harbour."},{en:"How the crew splits the work, and which tasks only crew members can do, still needs checking with the community."}]},{textEn:"The Tao man goes to Kaiyuan Harbour to sort the plank boat and fishing gear with the boat crew",lines:[{en:"Wipe the hull clean, check the net section by section and note the torn spots."}]},{textEn:"The Tao man reports to the man elder: the boat and gear are ready",lines:[{en:"Good, all sorted. Now we wait for flying fish season."}]}],hint:{fromEn:"Host family",en:"The man elder wants the Tao man to go to the harbour and sort the plank boat and gear with the crew."}},{name:{en:"Imorod announces the flying fish season"},text:{whoEn:"Whole party is notified",coopEn:"No need to be there; just shows the season starting",seasonEn:"Start of the game year",preEn:"New game year",unlockEn:"Imorod enters flying fish season; the other villages follow on their own",kindEn:"Season notice"},steps:[{textEn:"Flying fish season begins (shows the season only, no need to be there)"}],hint:{fromEn:"Tao villagers",en:"This step completes by itself when flying fish season starts."}},{name:{en:"Go to sea for flying fish"},text:{whoEn:"Tao man",coopEn:"Solo (with an NPC boat crew)",seasonEn:"Flying fish season (by the local village)",preEn:"M1, M2, OF1 (traditional clothing; MS1 three-way preparation is optional)",kindEn:"Season + fishing ground (Tao man)"},steps:[{textEn:"The Tao man takes the job of going to sea from the man elder",lines:[{en:"Flying fish season is here. Go out with the boat crew. Only you go this time; the others wait on shore."},{en:"Put on the clothes woven at home first. Going out to sea on a boat is a serious thing."},{en:"Watch for the right moment. If it doesn't work, come back. Don't push yourself."},{en:"By tradition, men go to sea for flying fish. The game only has a timing practice; the real crews and rules still need checking with the community."},{en:'While at sea, you can only control the Tao man. Catch a fish, or tap "Give up", to return to shore and rejoin everyone.'}],solo:{taskEn:"Go to sea for flying fish"}},{textEn:"The Tao man paddles the plank boat out and waits for the moment a flying fish leaps (try again if you miss, or give up)",lines:[{en:"Caught one! Paddle back to shore."}]},{textEn:"The Tao man returns to shore and meets up with the Tao woman and the traveller",lines:[{en:"You're back! As long as you're safe."},{en:"Well done! We were watching from the shore the whole time."}]},{textEn:"The Tao man reports to the man elder: back safely",lines:[{en:"Coming back safe matters most. I'll teach you how to share the catch next time."}]}],hint:{fromEn:"Host family",en:"In flying fish season, the man elder will send the Tao man to sea. Only the Tao man can go; the others wait on shore."}},{name:{en:"Back to the beach to clean and share the catch"},text:{whoEn:"Tao man",coopEn:"Solo (with an NPC boat crew)",seasonEn:"Flying fish season (local)",unlockEn:"M5, M8, village ties",kindEn:"Season"},steps:[{textEn:"The Tao man reports to the man elder and goes back to the beach to clean the catch",lines:[{en:"The fish are back. Clean them on the beach first, then we share."}]},{textEn:"The Tao man and the boat crew share the catch evenly on the beach",lines:[{en:"One share for each person in the crew. Count them out one by one."},{en:"The flying fish catch is shared by the number of people in the crew. Everyone can see who gets more or less."}]},{textEn:"Report to the man elder: the catch is shared",lines:[{en:"Fair sharing keeps a crew together for a long time. Take the fish home and give them to the women of the house."}],gives:{toastEn:["Village ties","The catch was shared on the beach."]}}],hint:{fromEn:"Host family",en:"After the Tao man comes back from sea, he goes back to the beach to clean and share the catch with the crew."}},{name:{en:"Hand over the flying fish and sort them by kind"},text:{whoEn:"Tao man hands over, Tao woman takes over",coopEn:"Pair: Tao man + Tao woman, in front of the house",seasonEn:"Flying fish season"},steps:[{textEn:"The Tao man brings his share of flying fish home and gives it to the Tao woman",lines:[{en:"This is the crew's share for today."},{en:"Give them to me. I'll sort them with the elder."}]},{textEn:"The Tao woman and the woman elder sort the flying fish by kind",lines:[{en:"There are several kinds of flying fish. Keep each kind apart. How to sort them and who can eat which — follow the elder, don't decide yourself."},{en:"Okay, I'll lay them out the way you said."}],gives:{toastEn:["Sorting flying fish","The catch is handed over. Next, the fish need drying."]}}],hint:{fromEn:"Host family",en:"The Tao man brings the catch home and gives it to the Tao woman and the woman elder to sort."}},{name:{en:"Dry the fish and store them"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"Flying fish season",unlockEn:"Food store, dried flying fish card"},steps:[{textEn:"The woman elder asks the Tao woman to dry the fish",lines:[{en:"Good weather. Split the fish, rub in salt and hang them on the drying rack."}]},{textEn:"The Tao woman hangs the flying fish on the drying rack one by one",lines:[{en:"Split, wash, salt, and hang them up one by one."},{en:"The fish on the drying rack are a family's food for the whole year. Outsiders shouldn't touch them."}]},{textEn:"Report to the woman elder",lines:[{en:"Once dry, put them in the food store. This year's dried flying fish starts here."}],gives:{toastEn:["Dried flying fish card","The dried flying fish are in the food store."]}}],hint:{fromEn:"Host family",en:"After the flying fish are sorted, the Tao woman dries them on the host family's drying rack."}},{name:{en:"Cook a family meal"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"Flying fish season",unlockEn:"Boiled flying fish recipe card, M9"},steps:[{textEn:"The woman elder asks the Tao woman to make the family dinner",lines:[{en:"Flying fish today. Just boil it in plain water. Don't add anything else."}]},{textEn:"The Tao woman cooks a pot of boiled flying fish at the host family's house",lines:[{en:"When the water boils, put the fish in and cook a little longer."},{en:"Meals in flying fish season have rules about pots and methods. Each family is different; this still needs checking with the community."}]},{textEn:"Ask the woman elder to taste it",lines:[{en:"Just right. Call everyone home to eat."}],gives:{toastEn:["Boiled flying fish recipe card","The family meal is ready."]}}],hint:{fromEn:"Host family",en:"In flying fish season, the woman elder will ask the Tao woman to cook the family meal."}},{name:{en:"A day outside the village"},text:{whoEn:"Traveller",coopEn:"Pair: Traveller + any Tao member, outside the village",seasonEn:"Flying fish season (same time)",unlockEn:"Respect points, M9"},steps:[{textEn:"The elder asks the traveller to spend today outside the village",lines:[{en:"They're cleaning the catch on the beach today, so outsiders should stay away. Go for a walk outside the village and come back in the evening."}]},{textEn:"The traveller and a Tao member go to Qingqing Prairie in the south",lines:[{en:"Looking at the sea from here, we won't bother the people on the beach."},{en:"When we came back for summer holidays as kids, we were often sent here to play, so we wouldn't make trouble on the beach."}]},{textEn:"Return to the host family in the evening",lines:[{en:"You're back. Everyone noticed you knew to give them space."}],gives:{toastEn:["Respect event","The village saw that you knew to give space in flying fish season."]}}],hint:{fromEn:"Host family",en:"On the beach's busiest days in flying fish season, the elder will ask the traveller to go for a walk outside the village."}},{name:{en:"A family meal together"},text:{whoEn:"Whole party",coopEn:"Trio: whole party at the host family's house",seasonEn:"Flying fish season"},steps:[{textEn:"The whole party returns to the host family to eat together",lines:[{en:"Everyone's back. Sit down and eat."},{en:"What came from the sea, the fields and what we learned outside — it's all on this table today."},{en:"Busy all day. So this is how a meal comes together."}]},{textEn:"Listen to the host family elder after the meal",lines:[{en:"A family eating together — that's the most important thing in flying fish season."}],gives:{toastEn:["A family meal together","A day of flying fish season ends well."]}}],hint:{fromEn:"Host family",en:"The fish is cooked and the traveller is back. The whole party returns to the host family to eat together."}},{name:{en:"Storing flying fish (name to be confirmed)"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"Time to be confirmed",unlockEn:"Food store count"},steps:[{textEn:"The woman elder asks you to put away the dried flying fish",lines:[{en:"Put away the dried flying fish, each kind in its place, and work out how long it will last."}]},{textEn:"The Tao woman brings the dried flying fish in from the drying rack",lines:[{en:"Dry and hard. Put them away string by string."}]},{textEn:"Report to the woman elder",lines:[{en:"All stored. On the day flying fish season ends, we'll see how much is left."}],gives:{toastEn:["Storing flying fish","The dried flying fish in the food store are sorted."]}}],hint:{fromEn:"Host family",en:"Once the flying fish are dry, the woman elder will ask the Tao woman to store them."}},{name:{en:"End of flying fish (name to be confirmed)"},text:{whoEn:"Whole party is notified",coopEn:"No need to be there",seasonEn:"Time to be confirmed",unlockEn:'"Just right" count, Z1, next game year',kindEn:"Season notice"},steps:[{textEn:"Flying fish season ends (shows the season only, no need to be there)",lines:[{en:"Flying fish season is coming to an end. Each village, as the elders decide, reaches the day flying fish are eaten for the last time."},{en:"After this day, this year's flying fish are done, and everyone waits for them to return next year. The exact day and customs differ by village."}],gives:{toastEn:["End of flying fish","This year's flying fish season is over."]}}],hint:{fromEn:"Tao villagers",en:"This step completes by itself when flying fish season ends."}},{name:{en:"Tell women's fish, men's fish and elders' fish apart"},text:{whoEn:"Tao man catches, Tao woman prepares",coopEn:"Pair: Tao man + Tao woman",seasonEn:"Mostly outside flying fish season",unlockEn:"Fish field guide, boiled women's fish recipe card, F2"},steps:[{textEn:"The man elder explains how fish are sorted",lines:[{en:"Fish are sorted: some women can eat, some men eat, and some only elders eat."},{en:"Sort them when you catch them, so they don't end up in the wrong pot at home."}]},{textEn:"The Tao man fishes from the rocks by the harbour",lines:[{en:"Got one! This one's so bright."}]},{textEn:"The Tao woman and the woman elder sort the fish",lines:[{en:"This one is a women's fish — it's for us to cook. That one is a men's fish; keep it apart."},{en:"Got it — sort by colour and shape."}],gives:{toastEn:["Fish field guide","You learned to tell women's fish, men's fish and elders' fish apart."]}}],hint:{fromEn:"Host family",en:"The man elder wants to teach the Tao man and Tao woman how to tell kinds of fish apart."}},{name:{en:"Share the catch with the crew and relatives"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"Mostly outside flying fish season",unlockEn:"Village ties"},steps:[{textEn:"The Tao man goes to Kaiyuan Harbour and asks the plank boat fisher how to share this catch",lines:[{en:"One share for each crew member, and a little for the relatives too. The fish belong to everyone."}]},{textEn:"The Tao man takes fish to the relatives' homes",lines:[{en:"A little something from our family."}]},{textEn:"Report to the man elder",lines:[{en:"Fish you give away come back to you one day."}],gives:{toastEn:["Village ties","The catch was shared with the crew and relatives."]}}],hint:{fromEn:"Host family",en:"The fish caught should be shared with the crew and relatives. The Tao man should go ask how."}},{name:{en:"Dry 10 flying fish"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"Flying fish season",unlockEn:"Food store, W1",kindEn:"Season + count 10"},steps:[{textEn:"The woman elder asks: dry the family's share of flying fish together",lines:[{en:"The crew's share plus what the relatives brought makes ten. They're all yours to dry."}]},{textEn:"The Tao woman splits ten flying fish, salts them and hangs them on the drying rack",lines:[{en:"…eight, nine, ten. All hung up."}]},{textEn:"Report to the woman elder",lines:[{en:"All ten are dry. The food store will be in good shape this year."}],gives:{toastEn:["Food store","Ten dried flying fish are in the food store."]}}],hint:{fromEn:"Host family",en:"The Tao woman dries the family's share of flying fish, one by one."}},{name:{en:"Catch 6 fish and sort them together"},text:{whoEn:"Tao man catches, Tao woman prepares",coopEn:"Pair: Tao man + Tao woman",seasonEn:"Outside flying fish season",unlockEn:"Also counts for F2, fish field guide",kindEn:"Season + count 6 + fishing ground (Tao man catches)"},steps:[{textEn:"The man elder asks the Tao man to catch a few fish",lines:[{en:"Big waves in winter, so no going far out. Catch a few from the harbour rocks and bring them home for the Tao woman to sort."}]},{textEn:"The Tao man fishes from the rocks by the harbour",lines:[{en:"…four, five, six. That's enough. Home we go."}]},{textEn:"The Tao woman sorts the six fish into women's fish and men's fish",lines:[{en:"These three are for us to cook; those three go aside."},{en:"That was quick!"}]},{textEn:"Report to the man elder",lines:[{en:"The one who caught and the one who sorted both did it right. That's a family."}],gives:{toastEn:["Fish field guide","All six fish are sorted."]}}],hint:{fromEn:"Host family",en:"Outside flying fish season, the Tao man can fish by the harbour and bring the fish home for the Tao woman to sort."}},{name:{en:"Year's end: say something you learned this year in Tao, at the host family's home"},text:{whoEn:"Whole party",coopEn:"Trio: whole party at the host family's house",seasonEn:"A game year ends",preEn:"M11 and X03",unlockEn:"Ending, N1"},steps:[{textEn:"The whole party returns to the host family's pavilion as the year ends",lines:[{en:"A year has passed. Come, sit up here. Each of you, say one thing you learned this year in Tao."},{en:"akokey! I used to just nod when I came home. Now I can greet the elders in Tao."},{en:"soli, alibangbang… I remember the names of everything in the fields and at sea now."},{en:"Pongso no Tao, the Island of People. Thank you for bringing me home with you."},{en:"You didn't come back just to look around. As long as you remember this place, it will always be your home."},{en:"A game year has ended."}],gives:{toastEn:["One year","The year of coming home is over. Life on the island goes on."]}}],hint:{fromEn:"Host family",en:"Flying fish season is over. The whole party returns to the host family's pavilion to talk with the elder about the year."}}]},"/content/quests/member.json":{quests:[{name:{en:"Prepare ramie with the women elders: strip, soak and dry"},text:{whoEn:"Tao woman",coopEn:"Solo (NPC woman elder)",seasonEn:"Local off-season",unlockEn:"Ramie field guide, J2",kindEn:"Season"},steps:[{textEn:"The Tao woman takes a job from the woman elder: help prepare ramie on the porch",lines:[{en:"The ramie is in. It needs stripping, soaking and drying. The Tao woman will help the women elders on the porch — this takes a while."},{en:"The rest of you go do something else, then bring her some water."}],split:{f:{taskEn:"preparing ramie on the porch"}}},{textEn:"The Tao man or the traveller buys water at the Yayo grocery store and takes it to the porch",lines:[{en:"Water for the people working on the porch? Here you go."}]},{textEn:"Bring the water to the porch, help put the ramie away, and bring the Tao woman back to the party",lines:[{en:"Here — strip the ramie bark like this, soak it, then dry it."},{en:"So much faster with your help! It takes this many steps to become thread you can weave."},{en:"According to written records, women don't weave during the flying fish run, so this is done outside flying fish season. Details for each village still need checking with the community."}],gives:{toastEn:["Ramie field guide","Added to your notebook. The Tao woman is back with the party."]}},{textEn:"The Tao woman reports to the woman elder: the ramie is done",lines:[{en:"All the ramie is done? Well done. It goes fast when everyone helps."}]}],hint:{fromEn:"Host family",en:"The woman elder is looking for the Tao woman to help prepare ramie. The Tao woman will stay on the porch; the others should bring her water."}},{name:{en:"Watch a woman elder weave a short piece of cloth on the porch"},text:{whoEn:"Tao woman",coopEn:"Solo (NPC woman elder)",seasonEn:"Local off-season",unlockEn:"Weaving card (only a simple backstrap loom, no woven patterns or ceremonial clothes)",kindEn:"Season"},steps:[{textEn:"The Tao woman watches a woman elder weave a short piece of cloth on the porch",lines:[{en:"This is a backstrap loom. Lean your waist against this strap and the threads pull tight. Just watch for now."},{en:"Weaving has some taboos — for example, no touching the loom during mourning, and men don't step over the loom. This is only explained here; the game won't make you do it."},{en:"Woven patterns and ceremonial clothes aren't shown here. That waits until the community has reviewed it."}],gives:{toastEn:["Weaving card","Added to your notebook."]}}],hint:{fromEn:"Woman elder",en:"The ramie is dry. The Tao woman can come to the porch to watch the weaving."}},{name:{en:"Feed the pigs and chickens near the house"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"All year (repeatable)",unlockEn:"Livestock field guide (kois pig), food store"},steps:[{textEn:"Take a job from the woman elder: feed the pigs and chickens near the house",lines:[{en:"The pigs and chickens by the house need feeding. Can you do it? Come back and tell me when you're done."}]},{textEn:"The Tao woman feeds the pigs and chickens near the host family's house",lines:[{en:"The pigs and chickens are hungry. Feed them first."},{en:"After feeding, go check the food store."}]},{textEn:"Report to the woman elder: fed the pigs and chickens near the house",lines:[{en:"All fed? I checked. Well done."}]}],hint:{fromEn:"Host family",en:"The pigs and chickens by the house need feeding. The Tao woman will go."}},{name:{en:"Hidden: an afternoon in the thatch field (cut thatch for the host family)"},text:{whoEn:"Tao woman",coopEn:"Solo (NPC woman elder)",seasonEn:"Summer and autumn after flying fish season",preEn:"First time in the thatch field meeting a woman elder",unlockEn:"Thatch field guide, a word of praise from the host family",kindEn:"Hidden: first meeting"},steps:[{textEn:"The woman elder asks the Tao woman to cut thatch in the afternoon",lines:[{en:"The pavilion roof needs patching. Come cut thatch on the hillside with me this afternoon."}]},{textEn:"The Tao woman and the woman elder cut thatch and tie it in bundles",lines:[{en:"Put your gloves on. The leaf edges are sharp."},{en:"Tie what you cut into bundles of the same size. Easier to count when we carry them back."}]},{textEn:"Back home, the elder looks at the thatch the Tao woman tied",lines:[{en:"Very neat. Just like your Grandma used to do."}],gives:{toastEn:["Thatch field guide","The host family's elder praised the Tao woman."]}}],hint:{fromEn:"Host family",en:"On a winter afternoon, the host family's woman elder seems to be heading up the hillside for something."}},{name:{en:"Put the smaller flying fish around the edge for elders who can't get around"},text:{whoEn:"Tao man",coopEn:"Solo (NPC boat crew)",seasonEn:"Flying fish season (local)",unlockEn:'Village ties, "Sharing" story card',kindEn:"Season"},steps:[{textEn:"On the beach, the Tao man asks the crew what to do with the smaller flying fish",lines:[{en:"The small ones go around the edge, for elders who can't walk far or go to sea. They come and take them, or send a child."}]},{textEn:"The Tao man puts the smaller flying fish around the edge",lines:[{en:"These go here. When the elders come, they'll see them right away."}]},{textEn:"Report to the man elder",lines:[{en:"Those who can go to sea should think of those who can't. That's sharing."}],gives:{toastEn:['"Sharing" story card',"The smaller flying fish were kept for the elders who can't get around."]}}],hint:{fromEn:"Kaiyuan Harbour",en:"When sharing fish, the crew puts the smaller flying fish around the edge for the elders."}},{name:{en:"Repair field banks and water channels after flying fish season"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"After flying fish season (about July)",unlockEn:"Nature points, taro field care card"},steps:[{textEn:"Take a job from the woman elder: repair field banks and water channels after flying fish season",lines:[{en:"Flying fish season is over. The field banks and channels need fixing. It's up to you — come tell me when you're done."}]},{textEn:"After flying fish season, the Tao man repairs the field banks and water channels",lines:[{en:"The water damaged the bank a little. Patch it up and clear the channel too."},{en:"Which month the banks are repaired still needs checking with the community."}],gives:{toastEn:["Taro field care card","Added to your notebook."]}},{textEn:"Report to the woman elder: repaired the field banks and water channels",lines:[{en:"Banks and channels fixed? I checked. Well done."}]}],hint:{fromEn:"Host family",en:"Outside flying fish season, the field banks and channels need tidying."}},{name:{en:"Hidden: find the lost goat (kagling)"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"All year (day)",preEn:"First time seeing a goat herd by the hills",unlockEn:"Goat field guide, kagling added to Tao word cards",kindEn:"Hidden: first discovery"},steps:[{textEn:"The Imorod elder says: a goat didn't come home",lines:[{en:"The goat with a notch in its ear didn't come back yesterday. I looked on the mountain. Go look again."},{en:"If you see other families' goats, don't touch them. Only look for our family's mark."}]},{textEn:"The Tao man searches Mt. Hongtou first",lines:[{en:"These goats' ears are all whole… not ours."}]},{textEn:"The Tao man follows the road to Hutou Slope",lines:[{en:"Found it! Notched ear — that's the one. It ran so far."},{en:"Come on, kagling, let's go home."}]},{textEn:"Bring the goat back to Imorod",lines:[{en:"Good, it's back. Goats know the way, and people should too."}],gives:{toastEn:["Goat field guide","kagling (goat) added to Tao word cards."]}}],hint:{fromEn:"Imorod",en:"The Imorod elder seems to be counting goats — and keeps coming up one short."}}]},"/content/quests/modern.json":{quests:[{name:{en:"Instant noodles from the shop"},text:{whoEn:"Tao man, Tao woman",coopEn:"Solo",seasonEn:"All year",unlockEn:"Food store, village ties (depends on your choice)"},steps:[{textEn:"Go to the Yayo grocery store and hear the owner talk about instant noodles",lines:[{en:"Instant noodles sell best. Handy, they keep for ages, and we restock whenever the boat comes."},{en:"But when the sea is rough and the boats stop, the shelves empty fast."}]},{textEn:"Go home and ask the woman elder what she thinks",lines:[{en:"We all eat instant noodles when we're busy. It's not a bad thing."},{en:"But taro and fish need people to grow and catch them, or it all stops. Think about it yourselves."}],gives:{toastEn:["Food store","Instant noodles and taro from the fields are both on today's table."]}}],hint:{fromEn:"Yayo",en:"The Yayo grocery store owner says instant noodles are the best seller in the shop."}},{name:{en:"An abandoned taro field"},text:{whoEn:"Tao man, Tao woman",coopEn:'Choosing "Take over the field" needs a pair: Tao man + Tao woman',seasonEn:"Waiting for flying fish season",unlockEn:"Next year's R1"},steps:[{textEn:"The Ivalino taro field elder talks about a field gone wild",lines:[{en:"The owner of this field went to work in Taiwan. No one has looked after it for years — the weeds are taller than people."},{en:"Do you two want to try taking it over? I'll ask the owner's family first."}]},{textEn:"The Tao man clears the weeds from the field banks, and the Tao woman opens the water channel",lines:[{en:"The roots go so deep. Pull them out bit by bit."},{en:"The channel is open! Water is flowing into the field again."}]},{textEn:"Report to the taro field elder",lines:[{en:"A field needs people walking in it, or it goes wild. Next year you can plant."}],gives:{toastEn:["Take over the field","Next year you can plant taro in this field again."]}}],hint:{fromEn:"Ivalino",en:"The Ivalino taro field elder says one field has been abandoned for years."}},{name:{en:"Tourist high season (Iranmeylek)"},text:{whoEn:"Tao member leads, traveller joins",coopEn:"Pair: Tao member + Traveller, seeing the same thing from two sides",seasonEn:"Around flying fish season",unlockEn:"Respect points, village ties"},steps:[{textEn:"An Iranmeylek villager talks about the summer tourist season",lines:[{en:"In summer, Iranmeylek's night market is so lively, and scooters line the roadside."},{en:"More tourists means a bit more income for the village. But people also wander and take photos all over the beach and outside our homes."}]},{textEn:"The Tao member and the traveller stand together at Dongqing Bay, looking at the same beach",lines:[{en:"For us, this is where we go to sea — and it's our front door."},{en:"For tourists, it's a holiday. I'm a guest. Having fun is fine, but I should remember this is someone's home."}]},{textEn:"The traveller has a word with a couple who want to sit in a plank boat for a photo",lines:[{en:"Excuse me, the plank boats belong to Tao families. You can't sit in them for photos. The sea looks lovely from the roadside."},{en:"Oh, we didn't know. Thanks for telling us!"}],gives:{toastEn:["Respect event","The same thing from two sides: tourist high season."]}}],hint:{fromEn:"Iranmeylek",en:"Iranmeylek is so busy in summer. An Iranmeylek villager seems to have something to say."}},{name:{en:"Imported food"},text:{whoEn:"To be confirmed",coopEn:"To be confirmed",seasonEn:"From the community",unlockEn:"View from the community"},steps:[{textEn:"The grocery store owner talks about where the shop's goods come from",lines:[{en:"Rice, noodles, cans, drinks — the boat brings them all from Taiwan."},{en:"When the sea gets rough and the boats stop, the shelves go empty."}]},{textEn:"Go home and listen to the woman elder",lines:[{en:"We used to eat only what grew on the island. Now it's different — it's handy, but there are worries too."},{en:"The view in this part still needs to come from the community."}],gives:{toastEn:["Imported food","Most of the shop's goods come by boat."]}}],hint:{fromEn:"Yayo",en:"What the grocery store has seems to depend on whether the boat came in."}},{name:{en:"The modern challenge the Tao people see as most important"},text:{whoEn:"To be confirmed",coopEn:"To be confirmed",seasonEn:"From the community",preEn:"To be confirmed",unlockEn:"To be confirmed"},steps:[{textEn:"Ask the village culture worker: what do the Tao people see as the biggest modern challenge?",lines:[{en:"The biggest challenge? Everyone will give a different answer."},{en:"Go and ask around. Don't just listen to one person."}]},{textEn:"Ask the Iratay elder",lines:[{en:"Young people go to Taiwan for work. Often only the old and the kids are left in the village."}]},{textEn:"Ask the Tao language teacher",lines:[{en:"Fewer and fewer kids speak Tao. When a language goes, many stories go with it."}]},{textEn:"Ask the Iranmeylek woman elder",lines:[{en:"There doesn't seem to be as much in the sea as there used to be."}]},{textEn:"Go back and tell the village culture worker",lines:[{en:"Everything you heard is true — and each is only one part."},{en:"This page is left for the Tao people to write themselves."}],gives:{toastEn:["Modern challenges","This page is left for the Tao people to write themselves."]}}],hint:{fromEn:"Iraraley",en:"The village culture worker says to hear from several people about modern challenges."}},{name:{en:"Named after the child (optional epilogue)"},text:{whoEn:"Tao man, Tao woman",coopEn:"Solo",seasonEn:"After one game year",preEn:"Finish one game year",unlockEn:'Become Syaman- / Sinan-, unlocks "Teach a child to tell fish apart"'},steps:[{textEn:"On the pavilion, listen to the elder talk about names on the island",lines:[{en:"On the island, when someone has their first child, the parents' names change with the child."},{en:"The father becomes Syaman and the mother Sinan, followed by the child's name."},{en:"One day when you have children, everyone will call you by your child's name. Names grow along with the family."},{en:"Then we'll bring the child back and teach them about fish."}],gives:{toastEn:["Epilogue: named after the child",'Unlocked "Teach a child to tell fish apart".']}}],hint:{fromEn:"Host family",en:"A year has passed. The host family's elder on the pavilion seems to want to talk about names."}},{name:{en:"The health station doctor's tips on safe swimming and work"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"First aid card, faster recovery after injury"},steps:[{textEn:"Hear the health station doctor's tips on safe swimming and work",lines:[{en:"Check the waves and weather before going in. Never go in alone."},{en:"Put on your life jacket and do up the buckles. The reef rocks are sharp — wear non-slip shoes."},{en:"Drink plenty of water when drying fish or carrying wood, and rest at midday when it's hottest."}],gives:{toastEn:["First aid card","You noted the doctor's safety tips."]}}],hint:{fromEn:"Health station",en:"The health station doctor says there are a few things to watch for before swimming and working."}},{name:{en:"The dietitian's island food class"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",preEn:"Q06 or E1",unlockEn:"Nutrition card, Y3"},steps:[{textEn:"Listen to the dietitian's island food class",lines:[{en:"Taro and sweet potato give energy, fish gives protein, seaweed and wild greens give minerals."},{en:"The island's traditional table was already well balanced."}],gives:{toastEn:["Nutrition card","You learned about the nutrition of island food."]}}],hint:{fromEn:"Health station",en:"The health station dietitian is talking about island food."}},{name:{en:"Compare traditional and imported food with the dietitian (food sovereignty)"},text:{whoEn:"Tao woman + Traveller",coopEn:"Pair: Tao woman + Traveller, at the health station",seasonEn:"All year",preEn:"Y2 and G1",unlockEn:"Food sovereignty card, note added to the food store"},steps:[{textEn:"The Tao woman and the traveller compare traditional and imported food with the dietitian",lines:[{en:"The taro, flying fish and sweet potato at home — we grow and catch them all ourselves."},{en:"Imported noodles and cans are handy, but when the boat stops, they're gone."},{en:"Food you grow and catch yourselves is food the island's people can decide on for themselves. That's called food sovereignty."},{en:"So what we eat is something we can decide for ourselves too."}],gives:{toastEn:["Food sovereignty card",'The food store note now adds "food we can decide on ourselves".']}}],hint:{fromEn:"Health station",en:"After picking taro, the Tao woman can take the traveller to talk with the dietitian about traditional food."}}]},"/content/quests/night.json":{quests:[{name:{en:"Night stories under the pavilion"},text:{whoEn:"Whole party",coopEn:"All three listen together",seasonEn:"All year",unlockEn:'Story page "The black-winged flying fish"',kindEn:"Night · Story"},steps:[{textEn:"At night, sit on the host family's pavilion and hear the elder tell a story that can be shared",lines:[{en:"At night, everyone sits on the host family's pavilion as the sea breeze blows."},{en:"It's cool at night. Come sit. Today I'll tell a story everyone can hear."},{en:"Long ago, our ancestors didn't understand flying fish. They cooked every fish together, and they got sick."},{en:"Then a black-winged flying fish came in a dream and taught them when to catch, how to cook, and what must never be mixed."},{en:"So the flying fish rules weren't made up. The flying fish taught them to us."},{en:"This is the most widely told version. Each village tells it differently; it still needs checking with the community."}],gives:{toastEn:["Story page",'"The black-winged flying fish" was added to your notebook.']}}],hint:{fromEn:"Host family",en:"At night, the host family's elder often relaxes on the pavilion. Maybe there'll be a story."}},{name:{en:"Tide flats by headlamp (look, don't pick)"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year (at dusk low tide)",preEn:"S1 (headlamp), I2",unlockEn:"Hermit crab field guide",kindEn:"Dusk · Watching"},steps:[{textEn:"At dusk low tide, as it gets dark, wear a headlamp and explore the tide flats at Dongqing Bay",lines:[{en:"Creatures you can't see by day come out once it gets dark."},{en:"Keep your light low and put stones back after looking. The hermit crab is now in your field guide."}]}],hint:{fromEn:"Iranmeylek",en:"At low tide at night, take a headlamp to the tide flats and you'll see creatures you don't see by day."}},{name:{en:"Lanyu scops owl by the road (no flash)"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Lanyu scops owl field guide, photo",kindEn:"Night · Photo"},steps:[{textEn:"At night on the road from Iratay to Yayo, quietly listen for the scops owl and take one photo from afar",lines:[{en:"The elders don't really like talking about this bird at night. Let's just watch quietly and not copy its call."},{en:"No flash, no music to lure it. Take one photo from afar and move on."},{en:"The Lanyu scops owl is now in your field guide."}]}],hint:{fromEn:"Tourist",en:'They say that at night along the west coast road, you sometimes hear a "coo— coo" call.'}},{name:{en:"Evening party in Iratay"},text:{whoEn:"Whole party",coopEn:"All three together",seasonEn:"All year",unlockEn:"Trust of the Iratay villagers, party photo",kindEn:"Night · Village event"},steps:[{textEn:"At night, all three go to the Iratay school field for the evening party",lines:[{en:"You came! Grab something to eat first. The kids will sing soon."},{en:"So lively. So many elders came."},{en:"I brought the little pouch the Tao woman wove for me."},{en:"It looks lovely. This is our village's evening party, not a ceremony. Everyone relax."},{en:"Ask before taking photos of people."}]},{textEn:"Thank the Iratay woman elder",lines:[{en:"Had enough to eat? The sweet potatoes are from our field. Come help dig some in the daytime."}]}],hint:{fromEn:"Iratay",en:"The Iratay villagers invite everyone to the evening party at the school field."}},{name:{en:"Northeast monsoon on a winter night"},text:{whoEn:"Whole party",coopEn:"All three listen together",seasonEn:"Winter",unlockEn:'Notebook page "The island in winter"',kindEn:"Night · Story"},steps:[{textEn:"On a winter night, hear the host family elder talk about the northeast monsoon season",lines:[{en:"In winter the wind and waves are big, and the boats are all pulled ashore. The men mend nets and fix boats; the women look after the fields and the home."},{en:"When the sea won't let us out, we rest well and wait for the flying fish to return."},{en:"So winter has its own work too."}],gives:{toastEn:["Notebook",'"The island in winter" was added to your notebook.']}}],hint:{fromEn:"Host family",en:"On winter nights, the host family elder will talk about life in the monsoon season."}},{name:{en:"Night lights at Kaiyuan Harbour"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Photo",kindEn:"Night · Photo"},steps:[{textEn:"Photograph the harbour lights at Kaiyuan Harbour at night",lines:[{en:"The harbour, so busy by day, is calm and quiet at night."}]}],hint:{fromEn:"Harbour staff",en:"The lights of Kaiyuan Harbour are beautiful at night."}},{name:{en:"Moonrise at Dongqing Bay"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Photo",kindEn:"Night · Photo"},steps:[{textEn:"At night on the Dongqing Bay beach, photograph the moon rising over the sea",lines:[{en:"The moonlight is on the sea. You can even see the shadows of the plank boats."},{en:"Don't walk up to the boats, and don't sit in them."}]}],hint:{fromEn:"Iranmeylek",en:"Dongqing Bay isn't only lovely at sunrise. The moonrise is beautiful too."}},{name:{en:"Northeast monsoon waves (photo from the shore)"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"Winter",unlockEn:"Photo",kindEn:"Winter · Photo"},steps:[{textEn:"In winter on the Iraraley shore, photograph the monsoon waves from afar",lines:[{en:"Huge waves. No wonder the boats don't go out in winter."},{en:"Stay away from the shore rocks when the waves are big."}]}],hint:{fromEn:"Iraraley",en:"When the northeast monsoon comes in winter, the waves at Iraraley are especially big."}}]},"/content/quests/open.json":{quests:[{name:{en:"Arrive on Lanyu"},text:{whoEn:"Whole party",coopEn:"Trio: the whole party arrives together",seasonEn:"Game start",preEn:"Create the party and choose how to get to Lanyu",unlockEn:"Cultural note, Q02, Q03, Q04",kindEn:"Opening record: completes itself after the arrival scene; shown in the quest list, not a quest you can take again"},steps:[{textEn:"The whole party arrives on Lanyu together",lines:[{en:"The roles of men and women, taboos and food customs in this game are based on general practice in traditional Tao culture. They don't mean every family, village or era is exactly the same."},{en:"Villages differ in ceremony timing, taboo details and food habits, and modern families share work in many new ways. The game doesn't simulate ceremonies; it only shows the food and daily life the Tao people agree to share."},{en:"We're here! The boat has docked. This is Kaiyuan Harbour."},{en:"We're here! The plane landed safely. This is Lanyu Airport."},{en:"It's been so long. As kids we only came back for summer holidays. Then we studied and worked in Taiwan and couldn't even come back once a year."},{en:"This time we're staying longer. The elders say you only learn about home and the sea by coming back."},{en:"Let's rent a scooter at the rental shop by the harbour first, then go home and say hello to the family."},{en:"There's a scooter rental shop by Kaiyuan Harbour. Let's walk along the round-island road, rent a scooter, then go home to the family."},{en:"I can't wait! You lead, I'll follow."}]}],hint:{fromEn:"Tao villagers",en:"The whole party has arrived on the island together."}},{name:{en:"Rent a scooter"},text:{whoEn:"Anyone",coopEn:"Solo (once rented, the whole party can ride)",seasonEn:"All year",unlockEn:"has_scooter, 2D map, I1, K1–K6, X01, S1–S3"},steps:[{textEn:"Rent a scooter at the rental shop by Kaiyuan Harbour",lines:[{en:"Want to rent a scooter? One for you — all three of you can take turns."},{en:"Ride slowly on the round-island road at night. Land crabs often cross."}],gives:{toastEn:["Scooter rented",'The whole party can ride. Tap "Scooter" or press M to switch.']}}],hint:{fromEn:"Tao villagers",en:"There's a scooter rental shop right by Kaiyuan Harbour. The owner is standing at the door."}},{name:{en:"Check in at home"},text:{whoEn:"Tao man, Tao woman",coopEn:"Solo",seasonEn:"All year",unlockEn:"Host family, food store, R1"},steps:[{textEn:"The Tao man or Tao woman goes back to their home village and checks in with the host family elder",lines:[{en:"You're back! Tired from the trip?"},{en:"Everything's ready at home, and your friend is staying with us too. The food store is beside the house — we'll look after it together."}],gives:{toastEn:["Check in at home","The host family and food store were added to your notebook."]}},{textEn:"The elder takes everyone to sit on the pavilion beside the house",lines:[{en:"Come, sit on the pavilion. Leave your shoes down there. It's cool here and you can see the sea."},{en:"When you two were little, you were always on this pavilion listening to us talk."},{en:"In Taiwan I often thought of this pavilion. This time I want to really learn the ways of home."},{en:"Good. Coming home isn't just coming back to look — it's coming back to remember. Take your time. If you need anything, find me at the pavilion."}],gives:{toastEn:["The host family's pavilion","The host family's pavilion is everyone's home. Come here to chat and hear stories."]}}],hint:{fromEn:"Tao villagers",en:"The Tao man or Tao woman goes back to their home village to find the host family's elder."},twoHomes:{text:{coopEn:"The Tao man and Tao woman each go home, then meet at the host family's"},hint:{fromEn:"Tao villagers",en:"The Tao man and Tao woman each go back to their own village to check in with their family's elder (tap a portrait to switch members), then meet at the pavilion of the Tao man's home (the host family)."},steps:[{textEn:"The Tao man and Tao woman each check in at home",tasks:[{textEn:"The Tao man goes back to his village to check in with his family's elder",lines:[{en:"You're back! Tired from the trip?"},{en:"Everything's ready at home, and your classmate and friend are staying with us too. The food store is beside the house — we'll look after it together."}],gives:{toastEn:["The Tao man checked in at home","The host family and food store were added to your notebook."]}},{textEn:"The Tao woman goes back to her village to check in with her family's elder",lines:[{en:"You're back! You've grown so much, I almost didn't recognise you."},{en:"I hear you're staying at your classmate's? That's fine. Come home for meals often — the family field is waiting for your help too."},{en:"Okay, I'll come back often."}],gives:{toastEn:["The Tao woman checked in at home","The Tao woman's home is in your notebook too."]}}]},{textEn:"Both meet at the pavilion of the Tao man's home (the host family)",lines:[{en:"Come, sit on the pavilion. Leave your shoes down there. It's cool here and you can see the sea."},{en:"The Tao man grew up right here, listening to us talk. And you — your family's elders are old friends of ours. You're welcome on this pavilion any time."},{en:"In Taiwan I often thought of the pavilion at home. This time I want to really learn the ways of home."},{en:"Good. Coming home isn't just coming back to look — it's coming back to remember. Take your time. If you need anything, find me at the pavilion."}],gives:{toastEn:["The host family's pavilion","Everyone stays with the host family. Come to this pavilion to chat and hear stories."]}}]}},{name:{en:"First tour of Yayo"},text:{whoEn:"Traveller",coopEn:"Pair: Traveller + any Tao member",seasonEn:"All year",unlockEn:'Respect points "First visit", V1'},steps:[{textEn:"The traveller and a Tao member ask the Yayo elder to show them around the village",lines:[{en:"This is Yayo. Kaiyuan Harbour is right next door — lots of people arrive on the island here."},{en:"Greet people as you walk through the village. If you want a photo of a person or a house, ask first."},{en:"Okay, I'll ask first. Thank you!"}],gives:{toastEn:["Respect: First visit","The traveller's cultural respect starts being recorded."]}}],hint:{fromEn:"Host family",en:"The traveller and a Tao member should go to Yayo and find the Yayo elder."}},{name:{en:"Meet key people in the six villages"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",preEn:"Any four of K1–K6",unlockEn:"Village side quests, people pages, M1, F1, T1, E series",kindEn:"OR: any four"},steps:[{textEn:"Visit any four of the key people in the six villages (K1–K6)"}],hint:{fromEn:"Imorod elder",en:"The elder said he'd go and look first himself — meaning: don't wait for people to come to you, go to each village and find them. Visit the key people of the six villages."}},{name:{en:"Injury and the health station"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"Triggered by an injury",preEn:"Any gathering, swimming or sea activity",unlockEn:"Nutrition and health card, doctor and dietitian people pages, Y1, Y2"},steps:[{textEn:"The Tao woman scrapes herself on the reef at the tide flats and goes to the Imorod health station",lines:[{en:"I slipped on the reef just now and cut my foot."},{en:"Rinse it first and I'll clean it for you. It's not deep, don't worry."}]},{textEn:"The health station doctor checks the cut",lines:[{en:"Keep it dry for a few days and stay out of the water. Next time on the reef, wear non-slip shoes."},{en:"Come to our safety class when you have time. The dietitian is here too."}],gives:{toastEn:["Nutrition and health card","Doctor and dietitian people pages added to your notebook."]}}],hint:{fromEn:"Imorod",en:"If you get hurt on the reef, go to the Imorod health station."}},{name:{en:"Hear the host family elder explain the island's rules"},text:{whoEn:"Whole party",coopEn:"Trio: whole party at the host family's house",seasonEn:"All year",preEn:"Q03 and Q04",unlockEn:"Respect events start scoring, notebook rules page"},steps:[{textEn:"The whole party goes to the host family, and the elder sends the three off on separate errands",lines:[{en:"Everyone's here. Tonight I'll tell you about the island's rules. First, I need each of you to take care of a few things."},{en:"Tao man, go to Kaiyuan Harbour and ask the plank boat fisher about the sea lately. Tao woman, go to the porch and help the women elders bring things in. Traveller, go to the Yayo grocery store and buy what we need tonight."},{en:"When you're done, meet at the pavilion by the house. I'll talk once all three of you are here."},{en:"The party splits up: tap a portrait at the top left to switch members, and the camera jumps to where that member is."}],split:{m:{taskEn:"finding the plank boat fisher at Kaiyuan Harbour"},f:{taskEn:"helping the women elders on the porch"},t:{taskEn:"shopping at the Yayo grocery store"}}},{textEn:"Three errands (Tao man: Kaiyuan Harbour / Tao woman: porch / Traveller: grocery store)",tasks:[{textEn:"The Tao man goes to Kaiyuan Harbour to greet the plank boat fisher",lines:[{en:"The host family's elder sent you? The sea has been okay lately. Going out to sea can wait until the season comes."},{en:"Okay, I'll tell the elder."}]},{textEn:"The Tao woman goes to the porch and helps the women elders bring things in",lines:[{en:"Good timing. Help me bring in the things drying outside."},{en:"All done. I'll head back to the host family."}]},{textEn:"The traveller goes to the Yayo grocery store to buy water for tonight",lines:[{en:"Water? Sure, take these. Careful on the way."},{en:"Thanks! I'll take it back to the host family."}]}]},{textEn:"All three meet at the host family's pavilion",lines:[{en:"Everyone's back. Come sit on the pavilion."}]},{textEn:"The whole party sits on the host family's pavilion and hears the elder explain the island's rules",lines:[{en:"Everyone's here. Let me tell you the island's rules."},{en:"In flying fish season, there are many rules about the beach and the plank boats. Travellers shouldn't go onto the boat beach or touch the boats."},{en:"In flying fish season, girls don't touch the plank boats or get on them."},{en:"Don't go near village ceremonies, and don't take photos of them. If you want a photo of a person or a house, ask first."},{en:"The fish on the drying racks are a family's food for the whole year. Don't touch them."},{en:"Every family and every village does things a bit differently. If you're not sure, ask."}],gives:{toastEn:["Rules page",'"Island rules" added to your notebook. Respect events now count.']}}],hint:{fromEn:"Host family",en:"After checking in and the tour, all three go together to find the elder at the pavilion by the host family's house."}},{name:{en:"Visit the key person in Imorod"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Imorod side quests, people page"},steps:[{textEn:"Go to Imorod and visit the village's key person",lines:[{en:"You've come. Welcome to Imorod."},{en:"The health station is around Imorod too. Go there if you get hurt."},{en:"Come and sit again sometime. Get to know the village slowly."}]}],hint:{fromEn:"Villager",en:"They say there's an elder in Imorod who looks after visitors well. Ask around the village."}},{name:{en:"Visit the key person in Iratay"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Iratay side quests, people page"},steps:[{textEn:"Go to Iratay and visit the village's key person",lines:[{en:"You've come. Welcome to Iratay."},{en:"The airport is right next to our village. You can see every plane take off and land."},{en:"Come and sit again sometime. Get to know the village slowly."}]}],hint:{fromEn:"Villager",en:"They say there's an elder in Iratay who looks after visitors well. Ask around the village."}},{name:{en:"Visit the key person in Yayo"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Yayo side quests, people page"},steps:[{textEn:"Go to Yayo and visit the village's key person",lines:[{en:"You've come. Welcome to Yayo."},{en:"All the boats to Kaiyuan Harbour dock here."},{en:"Come and sit again sometime. Get to know the village slowly."}]}],hint:{fromEn:"Villager",en:"They say there's an elder in Yayo who looks after visitors well. Ask around the village."}},{name:{en:"Visit the key person in Iraraley"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Iraraley side quests, people page"},steps:[{textEn:"Go to Iraraley and visit the village's key person",lines:[{en:"You've come. Welcome to Iraraley."},{en:"Iraraley is on the north coast, and the tide flats are wide."},{en:"Come and sit again sometime. Get to know the village slowly."}]}],hint:{fromEn:"Villager",en:"They say there's an elder in Iraraley who looks after visitors well. Ask around the village."}},{name:{en:"Visit the key person in Iranmeylek"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Iranmeylek side quests, people page, E3"},steps:[{textEn:"Go to Iranmeylek and visit the village's key person",lines:[{en:"You've come. Welcome to Iranmeylek."},{en:"Dongqing Bay is one of the first places on the island to see the sunrise."},{en:"Come and sit again sometime. Get to know the village slowly."}]}],hint:{fromEn:"Villager",en:"They say there's an elder in Iranmeylek who looks after visitors well. Ask around the village."}},{name:{en:"Visit someone important in Ivalino"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Ivalino side quests, people page"},steps:[{textEn:"Go to Ivalino and visit the village's key person",lines:[{en:"You've come. Welcome to Ivalino."},{en:"Ivalino's underground houses are very well kept. Ask the owner before taking photos."},{en:"Come and sit again sometime. Get to know the village slowly."}]}],hint:{fromEn:"Villager",en:"They say there's an elder in Ivalino who looks after visitors well. Ask around the village."}}]},"/content/quests/outfits.json":{quests:[{name:{en:"Roots: Grandpa's boat crew"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"All year",preEn:"M1 (sorted the boat with the crew)",unlockEn:"Tao man's traditional clothing",kindEn:"Achievement + Roots (before M3 at sea)"},steps:[{textEn:"The host family elder mentions the Tao man's grandpa",lines:[{en:"You've sorted the boat with the crew, and soon you'll go to sea for the first time. Your grandpa started out just like this when he was young."},{en:"If you want to know about him, ask the elders who went to sea with him."}]},{textEn:"The Ivalino elder talks about Grandpa at sea",lines:[{en:"Your grandpa? He paddled steady and didn't talk much. When sharing fish, he always thought of others first."},{en:"Remembering a person's name and what he did — that's how you keep him at home."}],alt:{textEn:"The Iraraley elder talks about Grandpa at sea",lines:[{en:"Your grandpa? He paddled steady and didn't talk much. When sharing fish, he always thought of others first."},{en:"Remembering a person's name and what he did — that's how you keep him at home."}]}},{textEn:"The Yayo elder talks about Grandpa's boat crew",lines:[{en:"We were in the same boat crew for years. He mended nets the fastest. Clever hands."},{en:"Go on home. The elder at home has something for you."}],alt:{textEn:"The Imorod elder talks about Grandpa's boat crew",lines:[{en:"When I was young, I was in his boat crew for years. He mended nets the fastest. Clever hands."},{en:"Go on home. The elder at home has something for you."}]}},{textEn:"The host family's woman elder gives the Tao man clothes woven at home",lines:[{en:"The women of the family wove this together. You're going to sea with the crew and you've asked about your grandpa. You can wear it now."},{en:"Wear it to sea, to festivals and village events. You can change back whenever you like — just remember who wove it and why."},{en:`The Tao man unlocked "Traditional clothing". Change into it on the "Bag" page of the notebook. It doesn't include ceremonial items like the silver helmet or gold plates; when to wear it still needs checking with the community.`}],gives:{toastEn:["Clothing unlocked",`The Tao man's traditional clothing was added to the "Bag" page of the notebook.`]}}],hint:{fromEn:"Host family",en:"After the Tao man sorts the boat with the crew, the host family elder seems to want to tell him about his grandpa."}},{name:{en:"Roots: Grandma's weaving and taro field"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"Outside flying fish season",unlockEn:"Tao woman's traditional clothing",kindEn:"Achievement + Roots"},steps:[{textEn:"The Imorod weaving elder talks about the Tao woman's Grandma",lines:[{en:"The way you wind thread is just like your Grandma. She used to weave on the porch for a whole afternoon."},{en:"Her taro field is in Ivalino. Go ask the elders who used to work the field with her."}],alt:{textEn:"The Iratay woman elder talks about the Tao woman's Grandma",lines:[{en:"The way you wind thread is just like your Grandma. When we were young we often wove together on the porch for a whole afternoon."},{en:"Her taro field is in Ivalino. Go ask the elders who used to work the field with her."}]}},{textEn:"The Ivalino taro field elder talks about Grandma's field",lines:[{en:"Your family's elder looks after that field now. Your Grandma used to say a field needs people walking in it, or it goes wild."},{en:"Go and see it. When you come back, come to the porch at home."}],alt:{textEn:"The Iranmeylek woman elder talks about Grandma's field",lines:[{en:"When I was young I often went to Ivalino to help in your Grandma's field. Your family's elder looks after it now."},{en:"Your Grandma used to say a field needs people walking in it, or it goes wild. Go and see it. When you come back, come to the porch at home."}]}},{textEn:"The Tao woman walks into the family's taro field",lines:[{en:"So this is where Grandma used to work."},{en:"The Tao woman stands on the field bank for a while."}]},{textEn:"The host family's woman elder gives the Tao woman clothes woven at home",lines:[{en:"This was woven with thread from our home. Some of it was left by your Grandma."},{en:"You've learned to prepare ramie and wind thread, and you've walked Grandma's field. Wear it, and remember how these skills were handed down."},{en:'The Tao woman unlocked "Traditional clothing". Change into it on the "Bag" page of the notebook. When to wear it and its patterns still need checking with the community.'}],gives:{toastEn:["Clothing unlocked",`The Tao woman's traditional clothing was added to the "Bag" page of the notebook.`]}}],hint:{fromEn:"Elder",en:"Watching the Tao woman wind thread, the weaving elder seems to remember someone."}},{name:{en:"The Tao woman weaves a small straw pouch for the traveller"},text:{whoEn:"Tao woman + Traveller",coopEn:"Two working together",seasonEn:"All year",preEn:"IT-V2 (party invite), J1",unlockEn:"Traveller's everyday accessories (woven straw hat, small woven pouch)",kindEn:"Side quest"},steps:[{textEn:"Ask the weaving elder: what can the traveller wear to the party?",lines:[{en:"Going to the Iratay party? Traditional clothes belong to the Tao people. Friends from outside don't wear them."},{en:"But you could have the Tao woman weave you a small pouch and a straw hat to carry along. That would be nice."},{en:"Go buy a bundle of undyed cotton thread at the grocery store. I have the rest here."}]},{textEn:"The traveller buys cotton thread at the Yayo grocery store",lines:[{en:"Cotton thread? Making something, eh? This bundle is undyed. Here you go."}]},{textEn:"The Tao woman gets cloth scraps from the weaving elder",lines:[{en:"These are leftover thread ends and cloth edges. Use them. Keep it plain and simple — don't copy ceremonial patterns."}]},{textEn:"Back on the porch, the Tao woman weaves a straw pouch and hat for the traveller",lines:[{en:"Head down a little, let me measure… there! A straw hat and a little pouch."},{en:"So pretty! Thank you. I'll treasure them."},{en:'The traveller got a "Woven straw hat" and a "Small woven pouch". These are everyday accessories, not traditional clothing.'}],gives:{toastEn:["New accessories",'The traveller can wear the straw hat and carry the woven pouch from the "Bag" page of the notebook.']}}],hint:{fromEn:"Iratay",en:"After being invited to the party, find the Imorod weaving elder and have the Tao woman weave a small accessory for the traveller."}}]},"/content/quests/photo.json":{quests:[{name:{en:"Photograph Hongtou Rock"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (North coast rocks)"},steps:[{textEn:"The traveller photographs: Hongtou Rock",lines:[{en:"The round-island road goes right through the rock tunnel. The sea is just outside."},{en:"This name comes from tourist maps, based on its shape. The Tao people have their own name and story for this place — we still need them to tell us."}]}],hint:{fromEn:"Villager",en:"A little north of Kaiyuan Harbour, the road goes through a rock tunnel. At dusk the rock walls turn red."}},{name:{en:"Photograph Carp Rock"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (North coast rocks)"},steps:[{textEn:"The traveller photographs: Carp Rock",lines:[{en:"From this angle, it really does look a bit like a leaping fish."},{en:"This name comes from tourist maps, based on its shape. The Tao people have their own name and story for this place — we still need them to tell us."}]}],hint:{fromEn:"Villager",en:"There's a rock shaped like a fish. Look out to sea as you ride past."}},{name:{en:"Photograph Tank Rock"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (North coast rocks)"},steps:[{textEn:"The traveller photographs: Tank Rock",lines:[{en:"Like a tank that just drove up onto the shore… I bet that's not what the Tao people call it?"},{en:"In recent years, the village's young people have been bringing back the Tao place names and stories, one rock at a time."}]}],hint:{fromEn:"Villager",en:"There's a big rock on the northwest coast that tourists say looks like a tank."}},{name:{en:"View from Lanyu Lighthouse"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year",unlockEn:"Album +1 (North coast rocks)"},steps:[{textEn:"The traveller photographs: View from Lanyu Lighthouse",lines:[{en:"Looking down from the lighthouse, Kaiyuan Harbour and the whole west coast are right there."},{en:"The lighthouse area is an open viewpoint. Just walk up the trail — don't climb over the railings."}]}],hint:{fromEn:"Villager",en:"There's a lighthouse on the hill by Kaiyuan Harbour. You can see the whole harbour from there."}},{name:{en:"Five Holes Cave (photos from outside only)"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year",preEn:"Q04 and B1",unlockEn:"Album +1 (North coast rocks)",kindEn:"Restricted place: B1 first, photo from afar"},steps:[{textEn:"Go to the Five Holes Cave viewpoint and stay outside",lines:[{en:"Five Holes Cave may be a place the Tao people hold in respect. Look only from the viewpoint, from afar: don't go near, don't touch, don't pick anything up, and don't laugh loudly there."},{en:"I'll just look from here and not go any closer."}]},{textEn:"The traveller photographs Five Holes Cave from the viewpoint (without going near)",lines:[{en:"The cave mouths one after another — I'll only shoot from the road."},{en:"Album culture note: photographed only from outside, from afar, without going near."}]}],hint:{fromEn:"Village culture worker",en:"After hearing the distance rules for sacred places, you can photograph Five Holes Cave from the roadside outside. Don't go into the caves."}},{name:{en:"Photograph Jade Maiden Rock"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year",unlockEn:"Album +1 (North coast rocks)"},steps:[{textEn:"The traveller photographs: Jade Maiden Rock",lines:[{en:"The rock is hollow in the middle, with a small stone wedged inside."},{en:"Tourist maps call it Jade Maiden Rock. Some in the village say that long ago, people going to the tide flats at night would rest their torches on this rock. The name and story still need checking with the community."}]}],hint:{fromEn:"Villager",en:"On the road west of Iraraley, there's a big rock that's hollow in the middle."}},{name:{en:"Little Heaven Lake (from afar only)"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",preEn:"Q04 and B1",unlockEn:"Album +1 (Lakes and highlands)",kindEn:"May be sacred: B1 first, photo from afar"},steps:[{textEn:"Go to the Little Heaven Lake viewpoint and stay outside",lines:[{en:"Little Heaven Lake may be a place the Tao people hold in respect. Look only from the viewpoint, from afar: don't go near, don't touch, don't pick anything up, and don't laugh loudly there."},{en:"I'll just look from here and not go any closer."}]},{textEn:"The traveller photographs Little Heaven Lake from the viewpoint (without going near)",lines:[{en:"A small patch of water in the middle of the forest. So quiet."},{en:"Album culture note: photographed only from outside, from afar, without going near."}]}],hint:{fromEn:"Village culture worker",en:"After hearing the distance rules for sacred places, you can photograph Little Heaven Lake from the trail viewpoint."}},{name:{en:"Photograph Hen Rock"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (North coast rocks)"},steps:[{textEn:"The traveller photographs: Hen Rock",lines:[{en:"Hen Rock really looks like a hen sitting by the sea."},{en:"This name comes from tourist maps, based on its shape. The Tao people have their own name and story for this place — we still need them to tell us."}]}],hint:{fromEn:"Villager",en:"On the shore near Iraraley, there's a rock that looks like a sitting hen."}},{name:{en:"Stars over Twin Lions Rock"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"Night, no moon",unlockEn:"Album +1 (North coast rocks)",kindEn:"Time of day"},steps:[{textEn:"The traveller photographs: Stars over Twin Lions Rock"}],hint:{fromEn:"Villager",en:"On moonless nights there are so many stars over Twin Lions Rock."}},{name:{en:"Battleship Rock from the shore"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (East coast)"},steps:[{textEn:"The traveller photographs: Battleship Rock from the shore"}],hint:{fromEn:"Villager",en:"Battleship Rock is off the northwest coast. You can only photograph it from the shore."}},{name:{en:"Photograph Lovers' Cave"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year",unlockEn:"Album +1 (East coast)"},steps:[{textEn:"The traveller photographs: Lovers' Cave",lines:[{en:"The waves rush in under the stone arch. So loud."},{en:"The rocks are slippery and the waves are big. Don't climb to the cliff edge for photos."}]}],hint:{fromEn:"Villager",en:"On the cape north of Dongqing Bay, there's a huge sea arch."}},{name:{en:"Photograph Sky Crack"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (East coast)"},steps:[{textEn:"The traveller photographs: Sky Crack",lines:[{en:"The rock walls on both sides are so high — only a strip of sky is left in between."}]}],hint:{fromEn:"Villager",en:"There's a spot on the east coast where you only see a thin line of sky between two rock walls."}},{name:{en:"Sunrise at Dongqing Bay"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"Dawn; no plank boats in the shot during flying fish season",unlockEn:"Album +1 (East coast)",kindEn:"Time of day"},steps:[{textEn:"The traveller photographs the sunrise at Dongqing Bay",lines:[{en:"The sun is rising from the sea. The whole bay is golden."},{en:"On flying fish season mornings, the boats on the beach and the people getting ready for sea stay out of the shot. Only the sea and sky."}]}],hint:{fromEn:"Iranmeylek",en:"Dongqing Bay is one of the first places on the island to see the sunrise. Go at first light."}},{name:{en:"Photograph Helmet Rock"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (East coast)"},steps:[{textEn:"The traveller photographs: Helmet Rock",lines:[{en:"A round top — it really looks like a helmet."},{en:"This name comes from tourist maps, based on its shape. The Tao people have their own name and story for this place — we still need them to tell us."}]}],hint:{fromEn:"Villager",en:"On the road south of Ivalino, there's a big round-topped rock."}},{name:{en:"Photograph Elephant Trunk Rock"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (East coast)"},steps:[{textEn:"The traveller photographs: Elephant Trunk Rock",lines:[{en:"A column of rock, section by section, like an elephant dipping its trunk into the sea to drink."},{en:"This name comes from tourist maps, based on its shape. The Tao people have their own name and story for this place — we still need them to tell us."}]}],hint:{fromEn:"Villager",en:"On the southeast coast, there's a rock that looks like an elephant drinking by the sea."}},{name:{en:"Photograph Lanyu Waterfall"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (South coast)"},steps:[{textEn:"The traveller photographs: Lanyu Waterfall",lines:[{en:"Water trickles down the rock wall. So cool and fresh."},{en:"The rocks by the water are slippery. Just shoot from the roadside."}]}],hint:{fromEn:"Villager",en:"There's a small waterfall by the road in the south. More water after rain."}},{name:{en:"Photograph Dragon Head Rock"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (South coast)"},steps:[{textEn:"The traveller photographs Dragon Head Rock and Little Orchid Island out at sea",lines:[{en:"From here you can see Little Orchid Island out at sea."},{en:"Little Orchid Island (Jimagaod) is an important fishing ground for the Tao people. For the men, fishing there is hard and serious work. In the game you only look from afar."}]}],hint:{fromEn:"Villager",en:"Next to Dragon Head Rock on the south coast, you can see Little Orchid Island on clear days."}},{name:{en:"Big Heaven Lake (from afar only)"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",preEn:"Q04 and B1",unlockEn:"Album +1 (Lakes and highlands)",kindEn:"May be sacred: B1 first, photo from afar"},steps:[{textEn:"Go to the Big Heaven Lake viewpoint and stay outside",lines:[{en:"Big Heaven Lake may be a place the Tao people hold in respect. Look only from the viewpoint, from afar: don't go near, don't touch, don't pick anything up, and don't laugh loudly there."},{en:"I'll just look from here and not go any closer."}]},{textEn:"The traveller photographs Big Heaven Lake from the viewpoint (without going near)",lines:[{en:"A crater lake in the mountains. The water is like a mirror."},{en:"Album culture note: photographed only from outside, from afar, without going near."}]}],hint:{fromEn:"Village culture worker",en:"After hearing the distance rules for sacred places, you can photograph Big Heaven Lake from the trail viewpoint."}},{name:{en:"Photograph Old Man Rock"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (South coast)"},steps:[{textEn:"The traveller photographs: Old Man Rock",lines:[{en:"Like an old man sitting by the shore, quietly watching the sea."},{en:"This name comes from tourist maps, based on its shape. The Tao people have their own name and story for this place — we still need them to tell us."}]}],hint:{fromEn:"Villager",en:"On the south coast there's a rock that, from afar, looks like an old man sitting and watching the sea."}},{name:{en:"Dusk on Qingqing Prairie"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"Dusk",unlockEn:"Album +1 (South coast)",kindEn:"Time of day"},steps:[{textEn:"The traveller photographs: Dusk on Qingqing Prairie"}],hint:{fromEn:"Villager",en:"Go to Qingqing Prairie at dusk."}},{name:{en:"Badai Bay (in flying fish season, only from outside the village)"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year; only from afar during flying fish season",unlockEn:"Album +1 (South coast)",kindEn:"Season limits how you photograph"},steps:[{textEn:"The traveller photographs Badai Bay from the roadside outside the village",lines:[{en:"The bay curves all the way from Iratay to Imorod. Such a long beach."},{en:"In flying fish season, the beach belongs to those going to sea. Shoot only from the roadside outside the village — not the people or boats on the beach."}]}],hint:{fromEn:"Iratay",en:"On the road between Iratay and Imorod, you can see all of Badai Bay from afar."}},{name:{en:"Photograph Mantou Rock"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (West coast and harbour)"},steps:[{textEn:"The traveller photographs Mantou Rock from Hutou Slope",lines:[{en:"Looking north from Hutou Slope, the round one is Mantou Rock."},{en:"The Mantou Rock area is a place the Tao people respect and keep away from. Just look from Hutou Slope — don't walk over there."},{en:"So many goats around. They're not afraid of people at all."}]}],hint:{fromEn:"Yayo",en:"There's a big pavilion on Hutou Slope south of Kaiyuan Harbour. You can see Mantou Rock from there."}},{name:{en:"Photograph Kaiyuan Harbour"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (West coast and harbour)"},steps:[{textEn:"The traveller photographs: Kaiyuan Harbour"}],hint:{fromEn:"Harbour staff",en:"You can shoot it at Kaiyuan Harbour in the daytime."}},{name:{en:"Photograph Lanyu Airport (scenery only)"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (West coast and harbour)"},steps:[{textEn:"The traveller photographs: Lanyu Airport (scenery only)"}],hint:{fromEn:"Tao villagers",en:"The airport is next to Iratay village. Scenery only — no photos of passengers."}},{name:{en:"View down from the Lanyu Weather Station"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year (day)",unlockEn:"Album +1 (Lakes and highlands)"},steps:[{textEn:"The traveller photographs: View down from the Lanyu Weather Station",lines:[{en:"All the island's mountains and sea are below you, and clouds drift slowly over the peaks."},{en:"The weather changes fast up the mountain. If fog or rain comes in, head down early."}]}],hint:{fromEn:"Imorod",en:"Keep riding up the mountain road from Imorod. The weather station is at the end."}},{name:{en:"Ivalino traditional houses (ask the owner first)"},text:{whoEn:"Traveller; a Tao member comes along to ask",coopEn:"Pair: Traveller + any Tao member",seasonEn:"All year",preEn:"Q04 and the owner agrees",unlockEn:'Album +1, "Ask first" learning card',kindEn:"Permission"},steps:[{textEn:"The traveller and a Tao member first ask the Ivalino elder if it's okay to photograph the houses",lines:[{en:"May I take a photo of your house? Just the roof and stone walls, no people."},{en:"Good, you asked first. Shoot from the road. Don't go into the house, and don't photograph people resting."}]},{textEn:"The traveller photographs Ivalino's traditional houses from the road",lines:[{en:"The roofs are low and close to the ground, as if hiding from the sea wind."}]},{textEn:"Thank the Ivalino elder",lines:[{en:"Thank you for asking first. A house is where a family lives, not something to tour."}],gives:{toastEn:['Learning card "Ask first"',"Ask before photographing people or houses."]}}],hint:{fromEn:"Host family",en:"To photograph Ivalino's traditional houses, first ask a Tao member to come with you to ask the owner."}},{name:{en:"Plank boats at Iraraley Bay (ask the owner first)"},text:{whoEn:"Traveller; the Tao man comes along to ask",coopEn:"Pair: Traveller + Tao man",seasonEn:"Outside flying fish season (local)",preEn:"Q04 and the boat owner agrees",unlockEn:"Album +1",kindEn:"Season + permission"},steps:[{textEn:"The Tao man goes with the traveller to ask the Iraraley elder if it's okay to photograph the boat",lines:[{en:"Elder, my friend would like to photograph your boat. Is that okay?"},{en:"It's not flying fish season now, so you can. Don't touch the boat or sit in it. Stand back a bit."}]},{textEn:"The traveller photographs the plank boats at Iraraley Bay from afar",lines:[{en:"Red, white and black, with the prow curving up so high."}]},{textEn:"Thank the Iraraley elder",lines:[{en:"A boat belongs to a family and to its crew. Good of you to ask first."}]}],hint:{fromEn:"Iraraley",en:"Outside flying fish season, ask the Tao man to come with you to ask the boat owner before photographing the plank boats at Iraraley Bay."}},{name:{en:"Snorkelling at Hen Rock"},text:{whoEn:"Anyone (the member you're controlling)",coopEn:"Solo",seasonEn:"Local off-season; summer days with calm seas",preEn:"Q02 and S3 (life jacket)",unlockEn:"Underwater scene A (shows the member you're controlling), U2",kindEn:"Dive spot (tourist, anyone can go) + season + item"},steps:[{textEn:"Snorkel in the cove below Hen Rock (anyone can, wear a life jacket)",lines:[{en:"The water's so clear. Looking down, there's coral, and clownfish darting in and out."},{en:"This is a modern tourist snorkelling spot — anyone can come. No snorkelling at the village beaches in flying fish season, so it's only open outside the season."}],gives:{toastEn:["Underwater scene",'Added to "Album & underwater".']}}],hint:{fromEn:"Scooter rental owner",en:"The cove below Hen Rock is great for snorkelling. Borrow a life jacket first. No swimming in flying fish season."}},{name:{en:"Yayo Harbour drop-off: a shallow scuba dive with the dive coach"},text:{whoEn:"Anyone (the member you're controlling)",coopEn:"Solo (with the NPC dive coach)",seasonEn:"Local off-season; daytime",preEn:"U1 and first meeting with the dive coach",unlockEn:"Underwater scene B (shows the member you're controlling)",kindEn:"Dive spot (tourist, anyone can go) + AND + season"},steps:[{textEn:"At the dive shop by Kaiyuan Harbour, listen to the dive coach explain",lines:[{en:"I'm the dive coach here, and I grew up on the island. Today I'll take you to the ledge outside Yayo Harbour."},{en:"We'll stay at the edge of the ledge and won't go down the drop-off. No diving at the Yayo drop-off in flying fish season either — wait until it's over."}]},{textEn:"Follow the coach to the ledge outside Yayo Harbour for a shallow scuba dive",lines:[{en:"Past the ledge, the water suddenly turns deep blue, and a big school of fish swims by from the open sea."}],gives:{toastEn:["Underwater scene",'Added to "Album & underwater".']}}],hint:{fromEn:"Tao villagers",en:"There's a Tao dive coach at the dive shop by Kaiyuan Harbour. Go have a chat with him first."}}]},"/content/quests/recipes.json":{quests:[{name:{en:"Recipe: Ivalino boiled taro"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",preEn:"K6 (met someone in Ivalino)",unlockEn:'Recipe card "Boiled taro"',kindEn:"Recipe"},steps:[{textEn:'Ask the Ivalino woman elder about "Boiled taro"',lines:[{en:"Want to learn boiled taro? Sure. First get the ingredients ready: three taro."},{en:"Bring them when you have everything, and I'll show you."},{en:"How this dish is made, and its rules, differ by family and village. The details still need checking with the community."}]},{textEn:"Gather ingredients: three taro"},{textEn:'Bring the ingredients back to the Ivalino woman elder and learn "Boiled taro"',lines:[{en:"You have everything. Watch closely."},{en:"This is boiled taro. Wash and boil — the simplest dish, and the one we eat most. Ask the elders at home about other ways another day."},{en:'The recipe card is now in the notebook under "Food & nutrition". Seasoning and sharing rules still need checking with the community.'}],gives:{toastEn:["Recipe learned",'Recipe card "Boiled taro" added to your notebook.']}}],hint:{fromEn:"Ivalino",en:"There's an elder in Ivalino who makes boiled taro. Bring three taro and go find her."}},{name:{en:"Recipe: Imorod boiled flying fish"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"Flying fish season",preEn:"K1 (met someone in Imorod)",unlockEn:'Recipe card "Boiled flying fish"',kindEn:"Recipe"},steps:[{textEn:'Ask the Imorod woman elder about "Boiled flying fish"',lines:[{en:"Want to learn boiled flying fish? Sure. First get the ingredients ready: two flying fish."},{en:"Bring them when you have everything, and I'll show you."},{en:"How this dish is made, and its rules, differ by family and village. The details still need checking with the community."}]},{textEn:"Gather ingredients: two flying fish"},{textEn:'Bring the ingredients back to the Imorod woman elder and learn "Boiled flying fish"',lines:[{en:"You have everything. Watch closely."},{en:"This is boiled flying fish. Boil it with simple seasoning. Some foods must never be cooked with flying fish — that's the rule. Ask the elders at home about other ways another day."},{en:'The recipe card is now in the notebook under "Food & nutrition". Seasoning and sharing rules still need checking with the community.'}],gives:{toastEn:["Recipe learned",'Recipe card "Boiled flying fish" added to your notebook.']}}],hint:{fromEn:"Imorod",en:"There's an elder in Imorod who makes boiled flying fish. Bring two flying fish and go find her."}},{name:{en:"Recipe: Yayo dried flying fish"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"Flying fish season",preEn:"K3 (met someone in Yayo)",unlockEn:'Recipe card "Dried flying fish"',kindEn:"Recipe"},steps:[{textEn:'Ask the Yayo woman elder about "Dried flying fish"',lines:[{en:"Want to learn dried flying fish? Sure. First get the ingredients ready: three flying fish."},{en:"Bring them when you have everything, and I'll show you."},{en:"How this dish is made, and its rules, differ by family and village. The details still need checking with the community."}]},{textEn:"Gather ingredients: three flying fish"},{textEn:'Bring the ingredients back to the Yayo woman elder and learn "Dried flying fish"',lines:[{en:"You have everything. Watch closely."},{en:"This is dried flying fish. Prepare it, dry it, and store it to eat slowly later. Ask the elders at home about other ways another day."},{en:'The recipe card is now in the notebook under "Food & nutrition". Seasoning and sharing rules still need checking with the community.'}],gives:{toastEn:["Recipe learned",'Recipe card "Dried flying fish" added to your notebook.']}}],hint:{fromEn:"Yayo",en:"There's an elder in Yayo who makes dried flying fish. Bring three flying fish and go find her."}},{name:{en:"Recipe: Iraraley boiled yam"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",preEn:"K4 (met someone in Iraraley)",unlockEn:'Recipe card "Boiled yam"',kindEn:"Recipe"},steps:[{textEn:'Ask the Iraraley woman elder about "Boiled yam"',lines:[{en:"Want to learn boiled yam? Sure. First get the ingredients ready: two yams."},{en:"Bring them when you have everything, and I'll show you."},{en:"How this dish is made, and its rules, differ by family and village. The details still need checking with the community."}]},{textEn:"Gather ingredients: two yams"},{textEn:'Bring the ingredients back to the Iraraley woman elder and learn "Boiled yam"',lines:[{en:"You have everything. Watch closely."},{en:"This is boiled yam. Peel and boil — that's all. Soft and easy to digest. Ask the elders at home about other ways another day."},{en:'The recipe card is now in the notebook under "Food & nutrition". Seasoning and sharing rules still need checking with the community.'}],gives:{toastEn:["Recipe learned",'Recipe card "Boiled yam" added to your notebook.']}}],hint:{fromEn:"Iraraley",en:"There's an elder in Iraraley who makes boiled yam. Bring two yams and go find her."}},{name:{en:"Recipe: Iranmeylek boiled shellfish and seaweed"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",preEn:"K5 (met someone in Iranmeylek)",unlockEn:'Recipe card "Boiled shellfish and seaweed"',kindEn:"Recipe"},steps:[{textEn:'Ask the Iranmeylek woman elder about "Boiled shellfish and seaweed"',lines:[{en:"Want to learn boiled shellfish and seaweed? Sure. First get the ingredients ready: two shellfish and two handfuls of seaweed."},{en:"Bring them when you have everything, and I'll show you."},{en:"How this dish is made, and its rules, differ by family and village. The details still need checking with the community."}]},{textEn:"Gather ingredients: two shellfish, two handfuls of seaweed"},{textEn:'Bring the ingredients back to the Iranmeylek woman elder and learn "Boiled shellfish and seaweed"',lines:[{en:"You have everything. Watch closely."},{en:"This is boiled shellfish and seaweed. Wash and boil, and eat with taro or sweet potato — that's the taste of the sea. Ask the elders at home about other ways another day."},{en:'The recipe card is now in the notebook under "Food & nutrition". Seasoning and sharing rules still need checking with the community.'}],gives:{toastEn:["Recipe learned",'Recipe card "Boiled shellfish and seaweed" added to your notebook.']}}],hint:{fromEn:"Iranmeylek",en:"There's an elder in Iranmeylek who makes boiled shellfish and seaweed. Bring two shellfish and two handfuls of seaweed and go find her."}},{name:{en:"Recipe: Iratay taro and sweet potato"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",preEn:"K2 (met someone in Iratay)",unlockEn:'Recipe card "Taro and sweet potato"',kindEn:"Recipe"},steps:[{textEn:'Ask the Iratay woman elder about "Taro and sweet potato"',lines:[{en:"Want to learn taro and sweet potato? Sure. First get the ingredients ready: one taro and one sweet potato."},{en:"Bring them when you have everything, and I'll show you."},{en:"How this dish is made, and its rules, differ by family and village. The details still need checking with the community."}]},{textEn:"Gather ingredients: one taro, one sweet potato"},{textEn:'Bring the ingredients back to the Iratay woman elder and learn "Taro and sweet potato"',lines:[{en:"You have everything. Watch closely."},{en:"This is taro and sweet potato. Boil them separately and eat them together as a meal — simple, but filling. Ask the elders at home about other ways another day."},{en:'The recipe card is now in the notebook under "Food & nutrition". Seasoning and sharing rules still need checking with the community.'}],gives:{toastEn:["Recipe learned",'Recipe card "Taro and sweet potato" added to your notebook.']}}],hint:{fromEn:"Iratay",en:"There's an elder in Iratay who makes taro and sweet potato. Bring one taro and one sweet potato and go find her."}}]},"/content/quests/split.json":{quests:[{name:{en:"Before flying fish season, three errands"},text:{whoEn:"Whole party",coopEn:"Three split up (switchable)",seasonEn:"Before flying fish season (around the fish-calling festival)",unlockEn:"IM-M1, OF1 (M3 doesn't need to wait for it)",kindEn:"Three-way split + regroup"},steps:[{textEn:"The host family elder sends the three off to prepare for flying fish season",lines:[{en:"Flying fish season is almost here, and there's a lot to prepare at home. It's quicker if you three split up."},{en:"Tao man, go to Iranmeylek — the elder there will teach you to check ropes and paddles. Tao woman, go to the Iraraley taro field — the woman elder is preparing taro for flying fish season. Traveller, go to Iraraley and find the village culture worker to learn what visitors should mind in flying fish season."},{en:"When all three of you are done, meet back at the host family. We won't go on until everyone's here."},{en:"The party splits up: tap a portrait at the top left to switch members, and the camera jumps to where that member is. The story continues once all three are done and back at the host family."}],split:{m:{taskEn:"finding the elder in Iranmeylek"},f:{taskEn:"helping the woman elder at the Iraraley taro field"},t:{taskEn:"finding the culture worker in Iraraley"}}},{textEn:"Three-way preparation (Tao man: Iranmeylek / Tao woman: Iraraley taro field / Traveller: Iraraley)",tasks:[{textEn:"The Tao man learns to check ropes and paddles from the Iranmeylek elder",lines:[{en:"The host family sent you? Good. Before going to sea, check for yourself whether the ropes are worn or the paddles cracked."},{en:"The sea is the men's responsibility. If you don't understand, ask. Don't pretend."},{en:"Got it. I'll tell the elder."}]},{textEn:"The Tao woman helps the Iraraley woman elder prepare taro",lines:[{en:"In flying fish season the men go to sea, so the house needs enough taro. We women plan the field work."},{en:"Take these back to the host family."},{en:"Thank you, I'll take them back."}]},{textEn:"The traveller asks the village culture worker about visitor manners in flying fish season",lines:[{en:"In flying fish season, the beach and the boats have rules. Visitors don't go onto the beach, don't touch the boats, and don't photograph the people going to sea."},{en:"If you're not sure something is okay, ask first — or just don't do it."},{en:"Okay, I'll remember, and I'll remind other tourists too."}]}]},{textEn:"All three meet back at the host family",lines:[{en:"I checked the ropes and paddles."},{en:"I brought the taro back."},{en:"And I asked about the flying fish season rules."}]},{textEn:"Report to the host family elder and get ready for flying fish season",lines:[{en:"Everyone's back. The sea, the fields and the outside world — all three are covered, so flying fish season can go well."},{en:"Once Imorod announces the start of flying fish season, the Tao man's trip to sea with the crew will go more smoothly."}],gives:{toastEn:["Ready for flying fish season","All three did their part, and everyone is back at the host family."]}}],hint:{fromEn:"Host family",en:"Before flying fish season, the host family elder will send the three off to prepare. The story moves on once all three are done and back home."}},{name:{en:"Help the boat crew carry boat timber down the mountain"},text:{whoEn:"Tao man leaves the party; Tao woman + Traveller help",coopEn:"The Tao man leaves for a while; the others bring lunch and bring him back",seasonEn:"Outside flying fish season",preEn:"K4 (met someone in Iraraley), M1",unlockEn:"Tao man rejoins, trust of the Iraraley elder"},steps:[{textEn:"The Tao man takes a job from the Iraraley elder: carry timber down the mountain with the crew",lines:[{en:"The crew is bringing timber down the mountain today and we're short of hands. Come up with us — it'll take all day."},{en:"The others don't need to come up. At noon, bring food to the trailhead at the foot of the mountain and wait there. Don't go further in."},{en:"The Tao man has left the party for now, so you can't control him. Quests that need him are paused too."}],split:{m:{taskEn:"carrying boat timber down the mountain with the crew"}}},{textEn:"The Tao woman or the traveller gets lunch from the Iraraley woman elder",lines:[{en:"The people working up the mountain need a good meal. I've cooked taro and sweet potato — wrap it up and take it."},{en:"Just take it to the trailhead. Don't go into where the men are working."}]},{textEn:"Take lunch to the trailhead at the foot of the mountain and wait to come back with the Tao man",lines:[{en:"You're here! The timber's all down by the road, and I'm starving."},{en:"The woman elder cooked it. Eat up."},{en:"We waited right here and didn't go further in."}]},{textEn:"The Tao man reports to the Iraraley elder: the timber is down",lines:[{en:"Well done. Building a boat isn't one person's job. It's the whole crew and the whole family together."}]}],hint:{fromEn:"Iraraley",en:"The Iraraley elder needs the Tao man's help up the mountain. He'll leave the party for a while — remember to take him lunch at the trailhead at noon."}}]},"/content/quests/taro.json":{quests:[{name:{en:"Clear, level and water the field"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"Waiting for flying fish season"},steps:[{textEn:"Take a job from the woman elder: clear, level and water the field",lines:[{en:"The field needs redoing: clear it, level it and bring the water in. It's up to you. Come tell me when you're done."}]},{textEn:"The Tao man goes to the host family's taro field to help clear, level and water it",lines:[{en:"First move the loose stones out of the field, then clear the channel so the mountain water flows in."},{en:"According to written records, men usually clear taro fields, while women usually plant, weed and harvest. Each family is different; details still need checking with the community."}]},{textEn:"Report to the woman elder: cleared, levelled and watered",lines:[{en:"Field ready? I checked. Well done."}]}],hint:{fromEn:"Host family",en:"The host family's taro field needs levelling and watering first. Ask the Tao man to help."}},{name:{en:"Plant taro"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"To be confirmed"},steps:[{textEn:"Take a job from the woman elder: plant taro",lines:[{en:"The taro can go in now. It's up to you. Come tell me when you're done."}]},{textEn:"The Tao woman plants taro in the taro field",lines:[{en:"The water's in, so we can plant. I'll ask the elders at home about how and when."}]},{textEn:"Report to the woman elder: taro planted",lines:[{en:"All planted? I checked. Well done."}]}],hint:{fromEn:"Host family",en:"The field is ready. Now the Tao woman plants the taro."}},{name:{en:"Weed and look after the field"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"All year (repeatable)",unlockEn:"R4, R5, nature points, E2"},steps:[{textEn:"Take a job from the woman elder: weed and look after the field",lines:[{en:"The weeds are back in the field. Go pull them and tidy up. Come tell me when you're done."}]},{textEn:"The Tao woman weeds and looks after the taro field",lines:[{en:"Pull out the weeds so the taro grows well."}]},{textEn:"Report to the woman elder: weeded the field",lines:[{en:"All weeded? I checked. Well done."}]}],hint:{fromEn:"Host family",en:"The taro field needs weeding often. The Tao woman will look after it."}},{name:{en:"Harvest taro"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"To be confirmed",unlockEn:"Food store, R6, T5"},steps:[{textEn:"The woman elder says: the taro is ready to harvest",lines:[{en:"The leaves are big enough. Time to pick. Take the big ones and leave the small ones."}]},{textEn:"The Tao woman harvests taro in the family's taro field",lines:[{en:"Plant your feet, run your hand down the stem and pull the whole thing up."}]},{textEn:"Report to the woman elder",lines:[{en:"Well picked. Some go in the food store, some we cook today."}],gives:{toastEn:["Food store","The taro is harvested."]}}],hint:{fromEn:"Host family",en:"The taro has grown. The woman elder will send the Tao woman to harvest it."}},{name:{en:"The traveller helps with the harvest and learns to cook (more content for a female traveller)"},text:{whoEn:"Traveller",coopEn:"Pair: Traveller + Tao woman",seasonEn:"Outside festival times",preEn:'R3, respect "Learning"',unlockEn:"Respect points, taro card"},steps:[{textEn:"The woman elder lets the traveller come and pick taro",lines:[{en:"We're picking taro today. You come too. Watch how the Tao woman does it first, then try."}]},{textEn:"The traveller follows the Tao woman and tries harvesting in the taro field",lines:[{en:"Step slowly. Don't break the field bank."},{en:"It's out! So much heavier than I thought."}]},{textEn:"Go home and learn to cook taro",lines:[{en:"Wash the taro and put it in the pot whole. Nothing added — it's delicious."}],gives:{toastEn:["Taro card","The traveller harvested and learned to cook taro with the Tao woman."]}}],hint:{fromEn:"Host family",en:"The traveller can go pick taro with the Tao woman, then learn how to cook it."}},{name:{en:"Boiled taro"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"All year",unlockEn:"Boiled taro recipe card"},steps:[{textEn:"The woman elder asks the Tao woman to cook taro",lines:[{en:"Today's taro — just boil it whole."}]},{textEn:"The Tao woman washes the taro and puts it in the pot whole",lines:[{en:"When a chopstick goes in easily, it's done."}]},{textEn:"Ask the woman elder to taste it",lines:[{en:"Soft and fragrant. You know how to cook it now."}],gives:{toastEn:["Boiled taro recipe card","The Tao woman learned to make boiled taro."]}}],hint:{fromEn:"Host family",en:"After the harvest, the Tao woman can learn to cook taro."}},{name:{en:"Harvest 5 taro for the host family"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"To be confirmed",unlockEn:"Food store, W1, W2 (the same harvest also counts for R6)",kindEn:"Count 5"},steps:[{textEn:"The woman elder wants the Tao woman to pick five taro for the host family",lines:[{en:"We need five taro at home. Pick big ones."}]},{textEn:"The Tao woman picks five taro in the family's taro field",lines:[{en:"One, two, three, four, five. That's enough."}]},{textEn:"Give the taro to the woman elder",lines:[{en:"All five are big. Put them in the food store."}],gives:{toastEn:["Food store","Five taro are in the food store."]}}],hint:{fromEn:"Host family",en:"The host family needs five taro. The Tao woman goes to pick them."}}]},"/content/quests/tatala.json":{quests:[{name:{en:"Becoming an apprentice"},text:{whoEn:"Tao man",coopEn:"Solo (NPC elder)",seasonEn:"All year",preEn:"Q05, enough village ties (the main story is enough)"},steps:[{textEn:"The Tao man asks the man elder to teach him boat building",lines:[{en:"I want to learn to build boats. May I learn from you?"},{en:"Building a boat takes more than a day. It starts with knowing the trees. You need patience."},{en:"First, practise paddling with me near the shore to steady your hands."}],gives:{toastEn:["Becoming an apprentice","The man elder agreed to teach the Tao man boat building."]}}],hint:{fromEn:"Host family",en:"The village knows the Tao man now. He can ask the man elder to teach him boat building."}},{name:{en:"Practise near the shore with the elder"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"To be confirmed",unlockEn:"T3, V4, paddling mini-game",kindEn:"Fishing ground (Tao man)"},steps:[{textEn:"The Tao man practises paddling a plank boat near the harbour with the elder",lines:[{en:"Put the paddles in together so the boat doesn't rock. Watch the waves, not the paddle."},{en:"It feels steadier now."}]},{textEn:"Back on shore, listen to the elder",lines:[{en:"Your hands are much steadier. Next time I'll take you up the mountain to see the trees."}],gives:{toastEn:["Paddling practice","The Tao man can now paddle a plank boat near the shore."]}}],hint:{fromEn:"Host family",en:"After becoming an apprentice, the man elder will take the Tao man to practise near the shore."}},{name:{en:"Learn the boat-building trees on the mountain"},text:{whoEn:"Tao man; the traveller may watch",coopEn:"The Tao man can go alone; for the traveller to watch, a pair: Tao man + Traveller",seasonEn:"Waiting for flying fish season"},steps:[{textEn:"The Tao man goes up the mountain with the elder to learn the boat-building trees",lines:[{en:"A tree for a boat has to grow in the right place, and you must ask the family that owns it."},{en:"Each kind of wood goes in a different part of the boat. The Tao people will teach you the tree names later."},{en:"I've noted what the bark and leaves look like."}]},{textEn:"Report to the elder after coming down",lines:[{en:"Know your trees and you'll build a good boat. Once the timber is dry, we can join the planks."}],gives:{toastEn:["Boat-building trees","The Tao man learned the trees used for building boats."]}}],hint:{fromEn:"Host family",en:"Outside flying fish season, the man elder will take the Tao man up Mt. Dasen to see the trees."}},{name:{en:"Build the plank boat"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"Waiting for flying fish season"},steps:[{textEn:"The man elder says: time to start joining the planks",lines:[{en:"The timber is dry. We can begin. Go slowly with the planks — one wrong board and the whole boat leaks."}]},{textEn:"Beside the house, the Tao man joins the boat planks one by one and fixes them with wooden pegs",lines:[{en:"This one's lined up… now the next."}]},{textEn:"The Tao man paints the hull red, white and black",lines:[{en:"The colours are just as the elders at home taught."},{en:"Hull patterns belong to each family. The game only shows simple colours."}]},{textEn:"Ask the man elder to look at the new boat",lines:[{en:"This is your boat now. Look after it like you look after family."}],gives:{toastEn:["A boat of his own","The Tao man finished his own plank boat."]}}],hint:{fromEn:"Host family",en:"After learning the boat-building trees, the Tao man can start building the plank boat."}},{name:{en:"Taro for the new boat's launch (optional, whole part to be confirmed)"},text:{whoEn:"Tao man, Tao woman; the traveller only if invited by the host",coopEn:"Trio: Tao man + Tao woman + Traveller",seasonEn:"At completion (to be confirmed)",unlockEn:"Village ties"},steps:[{textEn:"The woman elder and the Tao woman prepare taro for the new boat's launch",lines:[{en:"When a new boat is launched, the family prepares taro. I've picked these — you hold them."}]},{textEn:"The host family elder invites the traveller along",lines:[{en:"The new boat is being launched, and you're a friend of our family. Come with us. Just watch from the back, and no photos."},{en:"Thank you for inviting me. I'll stand back and won't take photos."}]},{textEn:"The whole party watches the new boat launch from the shore",lines:[{en:"The new boat's launch ceremony is done by the family and the crew. The game doesn't show the ceremony itself."},{en:"(quietly) What a beautiful boat."}],gives:{toastEn:["New boat launched","Family and friends together welcome the new plank boat."]}}],hint:{fromEn:"Host family",en:"The Tao man's new boat is finished. Before the launch, the family prepares taro and will invite the traveller."}},{name:{en:"Catch flying fish in your own boat"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"Flying fish season (local)",unlockEn:"Another source of flying fish, T7",kindEn:"Season + fishing ground (Tao man)"},steps:[{textEn:"The Tao man tells the man elder: he's taking his own boat to sea",lines:[{en:"First time in your own boat — don't push yourself. If you can't judge it, come back."},{en:'While at sea, you can only control the Tao man. Catch a fish, or tap "Give up", to return to shore and rejoin everyone.'}],solo:{taskEn:"Catch flying fish in your own boat",giveUp:[{en:"The waves are too big today. Back to shore."},{en:"Safety first. Try again next time."}]}},{textEn:"The Tao man paddles his own plank boat out for flying fish",lines:[{en:"Caught one! My own boat, my own fish."}]},{textEn:"The Tao man returns to shore and meets up with the Tao woman and the traveller",lines:[{en:"You're back! Your own boat paddles so steady."},{en:"We were watching from the shore the whole time."}]},{textEn:"Report to the man elder",lines:[{en:"Your boat's first time bringing fish home. Good."}],gives:{toastEn:["A boat of his own","The Tao man caught flying fish in his own boat."]}}],hint:{fromEn:"Host family",en:"In flying fish season, the Tao man can take his own plank boat to sea."}},{name:{en:"Night torch fishing for flying fish (big boat)"},text:{whoEn:"Tao man",coopEn:"Solo (NPC big-boat crew)",seasonEn:"Flying fish season, at night",unlockEn:"Growth skill",kindEn:"Season + time + fishing ground (Tao man)"},steps:[{textEn:"At night, the man elder asks the Tao man to join the big-boat crew",lines:[{en:"Tonight the big boat (cinedkeran) goes out to call flying fish with torches. Go with the crew and listen to the captain."},{en:"While at sea, you can only control the Tao man."}],solo:{taskEn:"at sea with the big-boat crew at night",giveUp:[{en:"The waves are too big today. Back to shore."},{en:"Safety first. Try again next time."}]}},{textEn:"The Tao man goes out at night with the big-boat crew and scoops flying fish by torchlight",lines:[{en:"The moment the torch lights up, the flying fish jump right over!"},{en:"Everyone paddles together and scoops together."}]},{textEn:"Return to shore near dawn and meet up with everyone",lines:[{en:"You're back. As long as you're safe."}]},{textEn:"Report to the man elder",lines:[{en:"Now that you've been out with the big boat, you're one of the crew."}],gives:{toastEn:["Growth","The Tao man learned to work together on the big boat."]}}],hint:{fromEn:"Host family",en:"On flying fish season nights, the big boat goes out with torches. The man elder may come looking for the Tao man."}},{name:{en:"Little Orchid Island (whole part awaits community approval)"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"To be confirmed",unlockEn:"Hidden story"},steps:[{textEn:"The man elder talks about Little Orchid Island",lines:[{en:"Jimagaod is a very important fishing ground for us. The currents are strong, so we're very careful. Only men go."},{en:"Come with me today and paddle close to have a look. We won't land. We'll look and come back."}],solo:{taskEn:"paddling toward Little Orchid Island with the elder",giveUp:[{en:"The waves are too big today. Back to shore."},{en:"Safety first. Try again next time."}]}},{textEn:"The Tao man paddles a plank boat with the elder and looks at Little Orchid Island from afar",lines:[{en:"The island is getting closer… and the waves are getting bigger."},{en:"This is far enough. Remember how it looks. We're going back."}]},{textEn:"Return to shore and meet up with everyone",lines:[{en:"You were gone so long! How was it out there?"},{en:"…I'll tell you about it slowly, another time."}]},{textEn:"Report to the man elder",lines:[{en:"The stories from over there — I'll tell you when you're a bit older."}],gives:{toastEn:["Hidden story","The Tao man has seen Little Orchid Island from afar."]}}],hint:{fromEn:"Host family",en:"Once the Tao man has his own boat, the man elder gazes at the sea to the south, as if remembering something."}}]},"/content/quests/tide.json":{quests:[{name:{en:"Read the tide clock"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year"},steps:[{textEn:"Ask the Kaiyuan Harbour staff to teach you the tide clock",lines:[{en:"Check the tide before going to sea or onto the tide flats."},{en:"There are about two low tides a day. I've put the tide clock at the top of the screen — go to the tide flats at low tide."}],gives:{toastEn:["Tide clock","The top of the screen shows high or low tide. For now it's simplified to low tide at dawn and dusk."]}}],hint:{fromEn:"Scooter rental owner",en:"The Kaiyuan Harbour staff know the tides best."}},{name:{en:"Morning on the tide flats"},text:{whoEn:"Tao woman; the traveller comes along",coopEn:"The Tao woman can go alone; for the traveller to join, a pair: Tao woman + Traveller",seasonEn:"At low tide",unlockEn:"Shellfish and seaweed cards (Tao names to come from the community), I3",kindEn:"Tide"},steps:[{textEn:"At low tide, the Tao woman goes to the Iraraley tide flats (the traveller can come along)",lines:[{en:"Low tide. The reef is showing."},{en:"We still need the community to tell us the Tao names for shellfish and seaweed. Today we'll note them in Chinese."}]}],hint:{fromEn:"Iraraley elder",en:`The elder asked, "What's in the sea?" — meaning go look at the tide flats at low tide. Learn the tide clock first, then ask the Tao woman to lead the way.`}},{name:{en:"Take only what you need"},text:{whoEn:"Tao woman, Traveller",coopEn:"Same as I2",seasonEn:"At low tide",unlockEn:"Nature points, C1",kindEn:"Tide"},steps:[{textEn:"At low tide, the Tao woman takes only what she needs from the tide flats (the traveller can watch)",lines:[{en:"This one's too small. Put it back. Enough for one meal is fine."},{en:"So you don't just pick up everything you see."}]},{textEn:"Report to the woman elder",lines:[{en:"Take only what you need, and the sea will always have more."}],gives:{toastEn:["Nature points","Took only what was needed."]}}],hint:{fromEn:"Host family",en:"At the tide flats at low tide, the woman elder says: take only what you need."}},{name:{en:"Land crabs at night"},text:{whoEn:"Tao woman; the traveller comes along",coopEn:"The Tao woman can go alone; for the traveller to join, a pair: Tao woman + Traveller",seasonEn:"Land crab season (to be confirmed), at night",preEn:"I2; can be taken early, headlamp from S1",unlockEn:"Land crab card, boiled land crab recipe card, C2",kindEn:"Take early, needs an item + time of day"},steps:[{textEn:"At night, the Tao woman takes a headlamp to look for land crabs near Iraraley (the traveller can come along)",lines:[{en:"The headlamp caught one — there's a crab walking by the road."},{en:"The land crab season and its rules still need checking with the community. Tonight we only look, no catching."}]}],hint:{fromEn:"Villager",en:"You often see crabs by the road at night. Remember your headlamp."}},{name:{en:"Help land crabs cross the road"},text:{whoEn:"Anyone",coopEn:"Solo (triggered when riding past)",seasonEn:"Land crab season, at night",preEn:"Q02, land crab season begins",unlockEn:"Nature points"},steps:[{textEn:"On land crab season nights, ride past slowly and stop to help land crabs cross the road",lines:[{en:"Stop! There's a land crab ahead. Go slowly, don't grab it."},{en:"On land crab season nights, mother crabs cross the road to release their young in the sea. Ride slower and you'll save one more."}],gives:{toastEn:["Nature points","You helped land crabs cross the road safely."]}}],hint:{fromEn:"Villager",en:"On summer nights, land crabs often cross the west coast road. Ride slowly."}},{name:{en:"The coconut crab you can't eat now"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",preEn:"Met a coconut crab",unlockEn:"Conservation card"},steps:[{textEn:"Ask the elder: can you eat the coconut crab you saw tonight?",lines:[{en:"People used to eat coconut crabs. Now there are fewer, and they're protected. Even if you see one, you can't catch it."},{en:"When there are more of them again, we'll see."}],gives:{toastEn:["Conservation card","Coconut crabs are protected now. No catching."]}}],hint:{fromEn:"Host family",en:"I think I saw a huge crab by the road last night… Ask the elder."}},{name:{en:"Buy a headlamp at the Yayo grocery store"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Headlamp (needed for C1)"},steps:[{textEn:"Buy a headlamp at the Yayo grocery store",lines:[{en:"A headlamp? Handy for walking at night. I've put the batteries in for you."}],gives:{toastEn:["Got: Headlamp",'Needed for "Land crabs at night" (C1).']}}],hint:{fromEn:"Tao villagers",en:"The Yayo grocery store has everything."}},{name:{en:"Buy sunscreen and water at the grocery store"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Sunscreen (needed for G3, also lowers the chance of sunburn)"},steps:[{textEn:"Buy sunscreen and water at the grocery store",lines:[{en:"The island sun is strong. Bring sunscreen and water."}],gives:{toastEn:["Got: Sunscreen, Drinking water","Picking shellfish on the tide flats (G3) needs sunscreen."]}}],hint:{fromEn:"Tao villagers",en:"The Yayo grocery store has sunscreen and water."}},{name:{en:"Pick 8 shellfish in one low tide (leave the small ones)"},text:{whoEn:"Tao woman; the traveller comes along",coopEn:"The Tao woman can go alone; for the traveller to join, a pair: Tao woman + Traveller",seasonEn:"At low tide",preEn:"I3; can be taken early, sunscreen from S2",unlockEn:"The same trip also counts for I3, recipe card, food store",kindEn:"Take early, needs an item + tide + count 8"},steps:[{textEn:"The woman elder takes the Tao woman to pick shellfish at low tide",lines:[{en:"Low tide. Bring sunscreen and water. Leave the small ones; just enough to eat."}]},{textEn:"The Tao woman picks shellfish on the tide flats (puts the small ones back)",lines:[{en:"These four are big enough. The small ones go back in the cracks."}]},{textEn:"A few more before the tide comes back",lines:[{en:"…seven, eight. The tide is coming in. Back to shore."}]},{textEn:"Report to the woman elder",lines:[{en:"Eight, all a good size. You remembered to put the small ones back. Good."}],gives:{toastEn:["Food store","Picked eight shellfish in one low tide."]}}],hint:{fromEn:"Host family",en:"At low tide, the woman elder will take the Tao woman to pick shellfish. Buy sunscreen first."}}]},"/content/quests/villages/imorod.json":{quests:[{name:{en:"Weaving elder: wind the ramie thread"},text:{whoEn:"Tao woman",coopEn:"Solo",seasonEn:"Winter (outside flying fish season)",unlockEn:"Ramie thread, OF2",kindEn:"a akes · Weaving"},steps:[{textEn:"The Imorod weaving elder asks the Tao woman to help wind thread",lines:[{en:"You've prepared ramie, so now learn to wind thread. Wind it well and the cloth weaves flat."},{en:"We don't weave during flying fish season, so we do more in winter."}]},{textEn:"Under the Imorod porch, the Tao woman winds the ramie thread round and round",lines:[{en:"One turn, two… keep your hands relaxed so the thread doesn't snap."}]},{textEn:"Give the wound thread to the weaving elder",lines:[{en:"Beautifully wound. Keep this roll — you'll need it later."}]}],hint:{fromEn:"Imorod",en:"In winter, the Imorod weaving elder needs help winding ramie thread."}},{name:{en:"Imorod elder: check the goats on the mountain"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"All year",unlockEn:"Seeing the goats on the mountain (unlocks A4)",kindEn:"a akey · Mountain"},steps:[{textEn:"The Imorod elder wants the Tao man to come up the mountain to check the goats",lines:[{en:"Men need to know the mountain. Today we'll go see our family's goats (kagling)."},{en:"Each family's goats have a different ear mark. If it's not yours, don't touch it."}]},{textEn:"The Tao man goes up Mt. Hongtou with the elder and counts the goats on the slope",lines:[{en:"One, two, three… the ones with a notched ear are ours. Five in all."}]},{textEn:"Report to the Imorod elder",lines:[{en:"Five, that's right. Now if a goat goes missing, you'll know where to look."}]}],hint:{fromEn:"Imorod",en:"The Imorod elder looks after the mountain. The Tao man can go up with him to check the goats."}}]},"/content/quests/villages/iranmeylek.json":{quests:[{name:{en:"Iranmeylek woman elder: take only what you need at low tide"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year (low tide)",unlockEn:"Shellfish, seaweed, tide flat rules",kindEn:"a akes · Tide flats"},steps:[{textEn:"The Iranmeylek woman elder takes you to the tide flats",lines:[{en:"Low tide. Come with me. The tide flats are everyone's kitchen. Leave some for tomorrow, and for others."}]},{textEn:"Follow the elder on the tide flats picking shellfish and seaweed, putting the small ones back",lines:[{en:"This one's too small. Put it back and let it grow."},{en:"What about this one?"},{en:"That one's fine. Just enough to eat — don't fill up."}]},{textEn:"Go back to the Iranmeylek woman elder",lines:[{en:"That's enough for today — just right. The tide is coming back. Let's go up."}]}],hint:{fromEn:"Iranmeylek",en:"At low tide, the Iranmeylek woman elder goes to the tide flats. You can learn from her how to pick."}},{name:{en:"Iranmeylek elder: ropes and paddles before going to sea"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"Summer (flying fish season)",unlockEn:"The Tao man's preparation for sea",kindEn:"a akey · Plank boat"},steps:[{textEn:"The Iranmeylek elder wants the Tao man to check everything himself",lines:[{en:"Last time I showed you. This time you do it. The ropes, the paddles — check them one by one."}]},{textEn:"The Tao man goes to the Dongqing Bay beach, pulls the ropes straight and checks the paddles",lines:[{en:"This section of rope is worn very thin. It needs replacing. The paddles are fine."}]},{textEn:"Report to the Iranmeylek elder",lines:[{en:"You saw it right. Trouble at sea often starts with one small rope."}]}],hint:{fromEn:"Iranmeylek",en:"In flying fish season, the Iranmeylek elder wants the Tao man to check the ropes and paddles himself."}},{name:{en:"Iranmeylek villager: the bay at dawn"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Trust of the Iranmeylek villagers",kindEn:"Key person"},steps:[{textEn:"An Iranmeylek villager talks about the sunrise tourists",lines:[{en:"Every morning, lots of tourists come to Dongqing Bay for the sunrise. More people is good, but there's more rubbish too."},{en:"And some sit in the plank boats for photos… those are other families' boats. Could you help me check on the bay?"}]},{textEn:"Pick up rubbish on the Dongqing Bay beach and politely ask tourists to move away from the plank boats",lines:[{en:"Excuse me, this is a Tao family's boat. Could you take your photo from the side? Thanks!"},{en:"Picked up plastic bottles and plastic bags."}]},{textEn:"Report to the Iranmeylek villager",lines:[{en:"Thank you. It's not that we don't welcome tourists — we just hope people remember that people live here."}]}],hint:{fromEn:"Iranmeylek",en:"An Iranmeylek villager is worried about the sunrise tourists. Go ask him what's wrong."}},{name:{en:"Iranmeylek villager: reasons for coming home"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"An Iranmeylek villager's story",kindEn:"Night · Story"},steps:[{textEn:"At night in Iranmeylek, hear a villager tell why he came back to the island",lines:[{en:"I worked in Taipei for over ten years. I took the metro every day and never saw the sea."},{en:"Then Dad's health got worse, so I came back. Now I run a guesthouse, lead tours, and learn to go to sea with the elders."},{en:"It's not easy for young people to come back. There's little work. But look at this sea, so quiet at night — I know I made the right choice."}]}],hint:{fromEn:"Iranmeylek",en:"At night, Iranmeylek villagers often relax by the bay."}}]},"/content/quests/villages/iraraley.json":{quests:[{name:{en:"Iraraley woman elder: weed the millet field"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"Summer",unlockEn:"Millet",kindEn:"a akes · Fields"},steps:[{textEn:"The Iraraley woman elder asks you to help pull weeds",lines:[{en:"The millet is up, and the weeds grow fast too. Help me weed — careful not to pull the millet."},{en:"A field needs regular care, or the weeds grow taller than the millet."}]},{textEn:"Pull weeds by the field with the woman elder",lines:[{en:"This one's a weed, this one's millet… they look so alike!"},{en:"The one with thinner leaves is millet. You'll get the hang of it."}]},{textEn:"Report to the Iraraley woman elder",lines:[{en:"Thank you. This little handful is from last year — take a look. I'll teach you how and when to harvest millet another time."}]}],hint:{fromEn:"Iraraley",en:"The Iraraley woman elder looks after the millet field and needs help weeding."}},{name:{en:"Iraraley elder: which boat to fix first this year"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"Winter",unlockEn:"Plank boat knowledge",kindEn:"a akey · Plank boat"},steps:[{textEn:"The Iraraley elder wants the Tao man to come look at the boats",lines:[{en:"In winter we decide which boat to fix first. Come to the beach with me. Just look — don't touch other families' boats."}]},{textEn:"The Tao man goes to the Iraraley beach with the elder to look at the plank boats",lines:[{en:"This boat's planks are cracking a little."},{en:"Sharp eyes. This one gets fixed first."}]},{textEn:"Report to the Iraraley elder",lines:[{en:"How and when to fix a boat is decided by the crew together. You looked very carefully today."},{en:"Girls and friends from outside watch from a bit further away."}]}],hint:{fromEn:"Iraraley",en:"In winter, the Iraraley elder goes to the beach to look at the boats and decide which one to fix first this year."}}]},"/content/quests/villages/iratay.json":{quests:[{name:{en:"Iratay woman elder: sweet potato harvest"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Sweet potato, permission to dig in the sweet potato field",kindEn:"a akes · Fields"},steps:[{textEn:"The Iratay woman elder asks you to help dig sweet potatoes",lines:[{en:"The sweet potatoes are ready. The field is our family's — help me, and I'll share some of what we dig."}]},{textEn:"Go to the Iratay sweet potato field and dig sweet potatoes with the elder",lines:[{en:"This one's huge!"},{en:"Gently. Don't break it while digging."}]},{textEn:"Report to the Iratay woman elder",lines:[{en:"Thanks for your help. Take these. If you want sweet potatoes later, just tell me first and you can dig in the field."}]}],hint:{fromEn:"Iratay",en:"The Iratay woman elder is harvesting sweet potatoes. Go help."}},{name:{en:"Iratay elder: the Tao man goes to sea with the crew again"},text:{whoEn:"Tao man",coopEn:"Tao man alone (the others wait on shore)",seasonEn:"Summer (flying fish season)",unlockEn:"Trust of the Iratay elder, flying fish",kindEn:"a akey · To sea alone"},steps:[{textEn:"The Tao man takes the job of going to sea from the Iratay elder",lines:[{en:"I hear you've been to sea in Yayo. Today, go out with our Iratay crew. Same as before — only you go."},{en:"If the sea is bad, come back. No one will laugh at you."},{en:'While at sea, you can only control the Tao man; the Tao woman and traveller wait on the Iratay beach. Catch a fish, or tap "Give up", to come back and rejoin them.'}],solo:{taskEn:"at sea with the Iratay boat crew",giveUp:[{en:"Back already? Good. Safety comes first. Go out again next time."}]}},{textEn:"The Tao man paddles the plank boat out and waits for the moment a flying fish leaps (try again if you miss, or give up)",lines:[{en:"Caught one! Paddle back."}]},{textEn:"The Tao man returns to the Iratay beach and meets the Tao woman and the traveller",lines:[{en:"You're back!"},{en:"We waited right here the whole time and didn't go near the boats."}]},{textEn:"The Tao man reports to the Iratay elder",lines:[{en:"As long as you're back safe. Share the fish with the crew first, then take some home for the elders."},{en:"If your grandpa could see you, he'd be so happy."}]}],hint:{fromEn:"Iratay",en:"In flying fish season, the Iratay elder will invite the Tao man to go to sea with the Iratay crew. Only the Tao man can go."}},{name:{en:"Iratay villager: Grandma back from the airport"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Trust of the Iratay villagers",kindEn:"Key person · Modern life"},steps:[{textEn:"An Iratay villager is going to pick up his mum at the airport",lines:[{en:"My mum went to a hospital in Taiwan for a check-up, and she's flying back today. There's no big hospital on the island, so seeing a doctor means a lot of travel."},{en:"Could you go help with her bags at the airport? I need to get the car ready first."}]},{textEn:"Go to Lanyu Airport and help Grandma with her bags",lines:[{en:"Grandma, let me carry your bags!"},{en:"Smiling, Grandma hands you the hospital papers and asks you to take them to the health station."}]},{textEn:"Give the hospital papers to the health station nurse",lines:[{en:"Thank you. We'll follow the Taiwan hospital's advice and visit Grandma at home regularly."},{en:"Seeing a doctor isn't easy for the island's elders. It matters that people help each other."}]},{textEn:"Report to the Iratay villager",lines:[{en:"Thank you so much. My mum says she'll cook sweet potatoes for you next time."}]}],hint:{fromEn:"Iratay",en:"An Iratay villager is going to the airport to pick up his mum, back from seeing a doctor."}},{name:{en:"Iratay villager: an invitation to the evening party"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Party invitation (NT4, OF3)",kindEn:"Key person"},steps:[{textEn:"An Iratay villager invites everyone to the village's evening party",lines:[{en:"These next few nights there's a village party on the school field. We eat together and listen to the kids sing. All three of you, come!"},{en:"The traveller doesn't need to dress up. If you really want to wear something, ask the Tao woman to sew you something small — the Imorod weaving elder can teach her."}],gives:{toastEn:["Party invitation","Go to the evening party at the Iratay school field at night (NT4)."]}}],hint:{fromEn:"Iratay",en:"An Iratay villager seems to have good news."}}]},"/content/quests/villages/ivalino.json":{quests:[{name:{en:"Ivalino taro field elder: replant taro shoots"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"All year",unlockEn:"Trust of the taro field elder",kindEn:"a akes · Taro field"},steps:[{textEn:"The Ivalino taro field elder asks you to help replant",lines:[{en:"We harvested a few days ago, and the empty spots need replanting. Take these taro shoots and push them into the mud."},{en:"We women know the fields best. Just follow me."}]},{textEn:"Go to the Ivalino taro field and push the taro shoots into the mud",lines:[{en:"The mud's so deep, my feet are sinking!"},{en:"Three taro shoots planted."}]},{textEn:"Report to the taro field elder",lines:[{en:"Nicely planted. It'll be a few months before it's grown. The water has to keep flowing, or the taro won't taste good."}]}],hint:{fromEn:"Ivalino",en:"After the harvest, the Ivalino taro field elder needs to replant taro shoots."}},{name:{en:"Ivalino elder: the rules of flying fish season"},text:{whoEn:"Whole party",coopEn:"All three listen together",seasonEn:"Summer (flying fish season)",unlockEn:'Notebook page "Flying fish season rules"',kindEn:"a akey · Flying fish season"},steps:[{textEn:"Hear the Ivalino elder explain the rules of flying fish season",lines:[{en:"In flying fish season, when to go to sea and how to share the fish are decided by the men together."},{en:"When a boat comes back, the fish go to the crew first, then to relatives. Elders who can't get around aren't forgotten either."},{en:"When flying fish season ends, we stop and let the fish go back. That's our respect for the sea."},{en:"Only some of the rules can be shared, and each village is different. This still needs checking with the community."}],gives:{toastEn:["Notebook",'"Flying fish season rules" was added to your notebook.']}}],hint:{fromEn:"Ivalino",en:"In flying fish season, the Ivalino elder will talk about its rules."}}]},"/content/quests/villages/yayo.json":{quests:[{name:{en:"Yayo woman elder: sort the family's food stores"},text:{whoEn:"Anyone",coopEn:"Solo",seasonEn:"Winter",unlockEn:"Trust of the Yayo woman elder",kindEn:"a akes · Food"},steps:[{textEn:"The Yayo woman elder asks you to help sort the food stores",lines:[{en:"The waves are big in winter and the boats can't go out. The dried flying fish from summer and the sweet potatoes from the field must last until next season."},{en:"What the family eats and how much we store — that's for us women to manage. Help me add two sweet potatoes."}]},{textEn:"Gather ingredients: two sweet potatoes"},{textEn:"Give the sweet potatoes to the Yayo woman elder",lines:[{en:"Good, put them here. Sweet potatoes keep longer somewhere dry. The dried flying fish should be checked often."},{en:"Just enough in store — not too much, not too little. Extra goes to the relatives."}]}],hint:{fromEn:"Yayo",en:"The Yayo woman elder is sorting the winter food stores. Take two sweet potatoes to help."}},{name:{en:"Yayo elder: mend the fishing net"},text:{whoEn:"Tao man",coopEn:"Solo",seasonEn:"Winter",unlockEn:"Fishing net knowledge",kindEn:"a akey · Fishing"},steps:[{textEn:"The Yayo elder asks the Tao man to mend a fishing net with him",lines:[{en:"No going to sea in winter, so it's a good time to mend nets. If we don't mend the summer nets now, it'll be too late."},{en:"Take it to the harbour, spread it out and see where it's torn."}]},{textEn:"The Tao man spreads the net out by the harbour and finds the holes",lines:[{en:"Three holes here, and the thread is loose over there."}]},{textEn:"Report to the Yayo elder and learn the mending knot",lines:[{en:"Loop the thread over, then pull it tight… yes, like that. Take it slowly — your hands will remember."}]}],hint:{fromEn:"Yayo",en:"In winter, the Yayo elder mends nets by the harbour. The Tao man can go help."}}]},"/content/quests/visitor.json":{quests:[{name:{en:"Ask if you can help"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year",unlockEn:'Respect "Learning"'},steps:[{textEn:"The traveller asks a Tao villager: is there anything I can help with?",lines:[{en:"Excuse me, is there anything I can help with?"},{en:"Sure, thanks for asking. Start by pulling the weeds on the field bank."},{en:"Next time, come to the field with the family and learn slowly."}],gives:{toastEn:["Respect: Learning","The traveller can now join the Tao members at the tide flats and the taro fields."]}}],hint:{fromEn:"Villager",en:"There are often elders busy at the taro fields. Ask if you can help."}},{name:{en:"Learning: join the Tao members"},text:{whoEn:"Traveller",coopEn:"Pair: Traveller + the leading Tao member (usually the Tao man for a male traveller, the Tao woman for a female traveller)",seasonEn:"Depends on the activity",preEn:'Respect "Learning"',unlockEn:"Traveller versions of I2 and R5"},steps:[{textEn:"The traveller asks the host family's woman elder if they can go to the field with the Tao members",lines:[{en:"May I come to the field with you today? I'll do as I'm told and won't touch anything."},{en:"Sure. Stay with the family. Watch what they do, and only help when you're asked."}]},{textEn:"The traveller follows the Tao members, passing things and pulling weeds on the field bank",lines:[{en:"So this is how you step on a field bank without breaking the channel."},{en:"The host family decides the field work. The traveller only helps with what they're asked to."}]},{textEn:"Go back to the host family and hear what the elder says",lines:[{en:"You worked hard today, and you knew to ask first. The whole family noticed."}],gives:{toastEn:["Respect: Trusted","The host family now feels at ease letting the traveller help."]}}],hint:{fromEn:"Host family",en:"The traveller can ask the host family's woman elder about going to the field with the Tao members."}},{name:{en:"Hear the elder's food stories"},text:{whoEn:"Traveller",coopEn:"Solo (NPC elder)",seasonEn:"All year",preEn:'Respect "Trusted"',unlockEn:"Story card"},steps:[{textEn:"The traveller sits on the host family's pavilion and hears the elder's food stories",lines:[{en:"Come, sit up here. Leave your shoes down there. Today let's talk about meals."},{en:"In flying fish season, the pot for flying fish used to be kept apart from the pot for other fish."},{en:"Women look after the taro in the fields; men bring flying fish back from the sea. A meal is made by the whole family together."},{en:'At meals, the elders take first. Guests wait until the host says "eat", then start.'},{en:"I'll remember. Thank you for treating me like family."}],gives:{toastEn:["Respect: Friend",'The elder now sees the traveller as a friend of the family. Story card "About meals" was added to your notebook.']}}],hint:{fromEn:"Host family",en:"The host family's elder often rests on the pavilion. The traveller can go sit and hear about meals in the old days."}},{name:{en:"Off-season: paddle a modern kayak and watch the Tao man paddle a plank boat"},text:{whoEn:"Traveller",coopEn:"Pair: Traveller + Tao man",seasonEn:"Outside flying fish season (local)",preEn:'Respect "Trusted" and T2; can be taken early, life jacket from S3',unlockEn:"Plank boat experience card",kindEn:"Take early, needs an item + season"},steps:[{textEn:"The traveller and the Tao man ask the host family elder's permission to go out on the water",lines:[{en:"It's not flying fish season, so you can go out on the sea. The Tao man paddles the plank boat — don't get on it."},{en:"Rent a modern kayak next to the scooter rental, put on a life jacket and just stay near the Tao man."},{en:"Okay, I'll paddle my kayak and won't touch the plank boat."}]},{textEn:"The Tao man paddles his family's plank boat outside the harbour and shows how to read the waves",lines:[{en:"Put the paddles in together so the boat doesn't rock. Look, the waves come from over there."}]},{textEn:"The traveller paddles a rented modern kayak alongside the plank boat",lines:[{en:"The island from the sea — the mountains are so green! I'll stay alongside, not too close."},{en:"Only the Tao man paddles the plank boat. When the traveller and the Tao woman go out, they use modern kayaks, and don't always go with the Tao man."}]},{textEn:"Thank the elder back on shore",lines:[{en:"As long as you're back safe. You knew to watch from the side and not touch the boat. That's good."}],gives:{toastEn:["Sea experience card","From a modern kayak, the traveller watched the Tao man paddle a plank boat."]}}],hint:{fromEn:"Host family",en:"Outside flying fish season, the traveller can borrow a life jacket, rent a modern kayak and paddle alongside the Tao man's plank boat."}},{name:{en:"Learn to be invited to a meal"},text:{whoEn:"Traveller",coopEn:"Trio: whole party at the host family's house",seasonEn:"Outside festival times",preEn:'Respect "Friend"',unlockEn:'Field guide page "The Tao table"'},steps:[{textEn:"The whole party waits at the host family's home to be invited to eat",lines:[{en:"The food's ready. Everyone come in and sit."},{en:'(quietly) Wait until the elder says "eat" before starting.'},{en:"Okay, I'll wait."},{en:"Eat, eat — don't be shy."}]},{textEn:"Thank the host family's woman elder after the meal",lines:[{en:"Thank you. The taro was so fragrant, and the fish was delicious."},{en:"You know to wait and to say thanks. Come back and eat with us often."}],gives:{toastEn:['"The Tao table"','Page "The Tao table" added to the field guide.']}}],hint:{fromEn:"Host family",en:"The host family already sees the traveller as a friend. At mealtime, everyone is at home together."}},{name:{en:"Learn net-knotting from the Tao man (more content for a male traveller)"},text:{whoEn:"Traveller",coopEn:"Pair: Traveller + Tao man",seasonEn:"All year",preEn:'Respect "Learning"',unlockEn:"Net-knotting card"},steps:[{textEn:"The traveller and the Tao man ask the Yayo elder to teach net-knotting",lines:[{en:"Want to learn net-knotting? You need patience. One knot at a time, no rushing."},{en:"The Tao man will tie one first for you to copy."}]},{textEn:"Back at the host family, the traveller practises knots following the Tao man's hands",lines:[{en:"Loop the thread over, pull tight, then thread it back."},{en:"…I think it's crooked. Again!"}]},{textEn:"Show the practice net to the elder",lines:[{en:"The knots are still loose, but you've got it. Next time we mend nets, you can come and help."}],gives:{toastEn:["Net-knotting card","The traveller learned the most basic net knot."]}}],hint:{fromEn:"Yayo",en:"The Yayo elder often mends nets outside his door. The traveller and the Tao man can go learn from him."}},{name:{en:"Borrow a life jacket from the scooter rental owner"},text:{whoEn:"Traveller",coopEn:"Solo",seasonEn:"All year",unlockEn:"Life jacket (needed for V4)"},steps:[{textEn:"The traveller borrows a life jacket from the scooter rental owner",lines:[{en:"Excuse me, could I borrow a life jacket?"},{en:"Sure. Always wear it properly in the water. Safety first."}],gives:{toastEn:["Got: Life jacket","Needed for snorkelling at Hen Rock (U1) and the off-season plank boat experience (V4)."]}}],hint:{fromEn:"Scooter rental owner",en:"You can borrow a life jacket from the scooter rental."}},{name:{en:"Hear the village culture worker explain sacred places and keeping your distance"},text:{whoEn:"Traveller + any Tao member",coopEn:"Pair: Traveller + Tao member (NPC culture worker explains)",seasonEn:"All year",unlockEn:"P05, P07, P18 can be photographed from afar; culture notes in the album; B3",kindEn:"About sacred places"},steps:[{textEn:"The traveller and a Tao member hear the village culture worker explain sacred places and keeping your distance",lines:[{en:"You want to photograph places like Five Holes Cave and the Heaven Lakes? Listen to me first."},{en:"Some places on the island are respected by the Tao people and also taboo. Some are linked to those who have passed away; some follow rules left by the ancestors."},{en:"At those places, just look from afar and shoot from the road. Don't go in, don't touch, don't pick up stones, and don't laugh loudly there."},{en:"I understand. When tourists ask me, I'll explain it the same way."},{en:"You can keep the photos, but write down where you took them and why only from afar. That's your culture note."}],gives:{toastEn:["Sacred places and distance",'Five Holes Cave and the Little and Big Heaven Lakes can be photographed from outside, from afar. The album now has a "Culture notes" space.']}}],hint:{fromEn:"Iraraley",en:"Before photographing Five Holes Cave or the Heaven Lakes, go to Iraraley with a Tao member and hear the village culture worker explain."}},{name:{en:"Hear about coastal limits before flying fish season"},text:{whoEn:"Traveller",coopEn:"Solo (NPC culture worker)",seasonEn:"Before the local flying fish season begins",unlockEn:"Hints for photographing from afar in flying fish season (P13, P21), respect points"},steps:[{textEn:"The traveller hears the village culture worker explain the coastal limits in flying fish season",lines:[{en:"Flying fish season is almost here. During that time, the village beaches belong to the people going to sea."},{en:"Visitors don't go onto the beach, don't swim in the sea in front of the village, and don't photograph the boats or the people going out."},{en:"If you want photos of the sea, take them from the roadside outside the village."},{en:"Okay. The Iranmeylek sunrise, Badai Bay — I'll shoot them all from the road."}],gives:{toastEn:["Flying fish season photo rules","When you photograph the Dongqing Bay sunrise or Badai Bay, the notebook will remind you of the flying fish season rules."]}}],hint:{fromEn:"Iraraley",en:"Before flying fish season begins, go hear the village culture worker talk about the coastal rules again."}}]},"/content/recipes/recipes.json":{recipes:[{name:{en:"Flying fish and taro"},stepsEn:"Traditionally, flying fish (fresh or dried) are often prepared with taro. When cooking, follow the rule that flying fish are never cooked with certain foods — a food custom in the culture, also told in the legend of the black-winged flying fish teaching the ancestors.",nutritionEn:'Protein and complex carbs go together perfectly for working days: flying fish give essential amino acids and fatty acids, taro gives longer-lasting energy and potassium. The health station notes put this pairing on both the "Traditional recipes" and "Nutrition" pages — each adds to the other; neither replaces the other.'},{name:{en:"Boiled taro"},stepsEn:"Taro washed and boiled is one of the most common ways to eat it. Peeling, cutting, how long to cook it and what to eat it with differ by family; this still needs checking with the community.",nutritionEn:"Taro is a gentle complex carb, rich in fibre and potassium. Boiling keeps the nutrients and needs no oil — good for work in the fields and at sea."},{name:{en:"Boiled flying fish"},stepsEn:"In flying fish season it's mostly boiled with simple seasoning. Flying fish have their own cooking and eating rules (such as not cooking them with certain foods); details still need checking with the community.",nutritionEn:"Flying fish give good protein, omega-3 fats and vitamin D. Boiling uses little oil and keeps it light."},{name:{en:"Dried flying fish"},stepsEn:"Flying fish caught in the season are prepared, dried and put in the food store, as food for the family later. How to prepare and dry them, and the rules, still need checking with the community; the game only shows what the community agrees to share.",nutritionEn:"Drying concentrates protein and minerals and keeps well. Portions and what to eat it with still need explaining by the community and the dietitian."},{name:{en:"Boiled yam"},stepsEn:"Peel the yam and boil it. Where and when to dig yams by the hills still needs checking with the community.",nutritionEn:"Yam's mucilage and starch are easy to digest. Eaten with protein foods, it's more balanced."},{name:{en:"Boiled shellfish and seaweed"},stepsEn:"Shellfish and seaweed picked on the tide flats at low tide, washed and boiled. Each village has its own rules on what can be picked and when; this still needs checking with the community.",nutritionEn:"Shellfish give protein, iron and zinc; seaweed has iodine and minerals. Boiled and light, often eaten with staples like taro and sweet potato."},{name:{en:"Taro and sweet potato"},stepsEn:"Taro and sweet potato boiled separately and eaten together as the staple. Portions and pairings still need checking with the community.",nutritionEn:"Two root crops together give plenty of starch, fibre and potassium — steady energy for working days."}]},"/content/songs.json":{songs:{s01:{titleEn:"01 aibangbang Fishing song",en:"Dad netted lots of flying fish",activityEn:"Flying fish boats returning, sharing the catch",sourceEn:"ePark Indigenous language site, Songs (Yami; made by the Indigenous Languages Research and Development Foundation)",licenseEn:"CC BY-NC-SA 4.0 (non-commercial, credit the source; commercial use needs separate permission from the foundation)",statusEn:"Provisional"},s10:{titleEn:"10 asa vasit Fishing song",en:"Carrying a fishing rod made of one vasit bamboo and two kawi bamboos",activityEn:"Shore fishing, sorting fish",sourceEn:"ePark Indigenous language site, Songs (Yami; made by the Indigenous Languages Research and Development Foundation)",licenseEn:"CC BY-NC-SA 4.0 (non-commercial, credit the source; commercial use needs separate permission from the foundation)",statusEn:"Provisional"},s05:{titleEn:"05 o sikalopi A fishing tale",en:"Oh! The sikalopi living by the road",activityEn:"Coming home with a full net bag",sourceEn:"ePark Indigenous language site, Songs (Yami; made by the Indigenous Languages Research and Development Foundation)",licenseEn:"CC BY-NC-SA 4.0 (non-commercial, credit the source; commercial use needs separate permission from the foundation)",statusEn:"Provisional"},s09:{titleEn:"09 mita mangayo Woodcutting song",en:"We're going to Nazag to cut wood",activityEn:"Learning trees on the mountain, carrying boat timber",sourceEn:"ePark Indigenous language site, Songs (Yami; made by the Indigenous Languages Research and Development Foundation)",licenseEn:"CC BY-NC-SA 4.0 (non-commercial, credit the source; commercial use needs separate permission from the foundation)",statusEn:"Provisional"},s02:{titleEn:"02 zing zing zing Little chubby pig",en:"The piglet wiggles on the beach and shakes off the sand",activityEn:"Feeding the pigs and chickens",sourceEn:"ePark Indigenous language site, Songs (Yami; made by the Indigenous Languages Research and Development Foundation)",licenseEn:"CC BY-NC-SA 4.0 (non-commercial, credit the source; commercial use needs separate permission from the foundation)",statusEn:"Provisional"},s03:{titleEn:"03 jika cimoy Stop raining",en:"A dark cloud in the sky — please don't rain",activityEn:"Rainy days, the weather station",sourceEn:"ePark Indigenous language site, Songs (Yami; made by the Indigenous Languages Research and Development Foundation)",licenseEn:"CC BY-NC-SA 4.0 (non-commercial, credit the source; commercial use needs separate permission from the foundation)",statusEn:"Provisional"},s08:{titleEn:"08 tana lilikey Cheeky siblings",en:"Even though we brothers and sisters are still small",activityEn:"Everyday life by the host family's stove",sourceEn:"ePark Indigenous language site, Songs (Yami; made by the Indigenous Languages Research and Development Foundation)",licenseEn:"CC BY-NC-SA 4.0 (non-commercial, credit the source; commercial use needs separate permission from the foundation)",statusEn:"Provisional"}}},"/content/ui.json":{origins:[{en:"Yayo",hintEn:"West coast, coming home / finding roots, with Kaiyuan Harbour on the doorstep."},{en:"Iraraley",hintEn:"The open north coast, with upper and lower villages and tide flats."},{en:"Iranmeylek",hintEn:"Dongqing Bay on the northeast coast, greeting the island's first light."},{en:"Ivalino",hintEn:"Southeast coast, the most complete village of traditional underground houses."},{en:"Imorod",hintEn:"South coast, where the flying fish legend began; the health station is here."},{en:"Iratay",hintEn:"Flat land in the southwest, with Lanyu Airport right next to the village."},{en:"Visitor from outside",taoEn:"Landing at Kaiyuan Harbour",hintEn:"Arriving at Kaiyuan Harbour. Look first, listen first, ask first — then go near the boats and houses."},{en:"Random",hintEn:"Let the sea wind decide where this journey starts."}],travel:[{en:"Yayo"},{en:"Iraraley"},{en:"Iranmeylek"},{en:"Ivalino"},{en:"Imorod"},{en:"Iratay"},{en:"Kaiyuan Harbour"},{en:"Lanyu Health Station",taoEn:"South coast · by Imorod"},{en:"Lanyu Airport",taoEn:"South-west · by Iratay"},{en:"Qingqing Prairie",taoEn:"Grassland at the south tip"}],help:{toastTouchEn:["Swipe bottom-left to move","One finger to turn the view","Two fingers to zoom"],toastDesktopEn:["WASD to move","Drag to turn the view","Scroll to zoom","E to interact"],touch:[{titleEn:"Moving and the scooter",bodyEn:'Swipe bottom-left to move. Open "Menu" at the bottom right and tap "Walk | Scooter" to ride the e-scooter. On a road it follows the road by itself; push sideways to turn off it. The round-island road is faster; field banks and docks slow you down automatically.'},{titleEn:"View and zoom",bodyEn:'Drag one finger to turn the view, pinch with two to zoom. The camera moves in when you enter a village and back out when you leave. "Menu" at the bottom right resets or adjusts the view, or turns the guide arrow off.'},{titleEn:"Interact and notebook",bodyEn:'Get close to a person or place, then tap the prompt or "Interact" at the bottom right. Tap someone or something to gather nearby and the party walks over to talk or gather. Open the notebook at the top right; tap the minimap to travel around the island.'},{titleEn:"Party and quests",bodyEn:'The three portraits at the top left are the Tao man, the Tao woman and the traveller. Tap one to switch who you control; the others follow. Tap the quest bar or the "Quests" page in the notebook (top right) to see active, finished and locked quests.'}],desktop:[{titleEn:"Moving and the scooter",bodyEn:'WASD or arrow keys to move; directions follow the screen. Press M or open "Menu" at the bottom right and tap "Walk | Scooter" to switch to the e-scooter. On a road it follows the road by itself; steer sideways to turn off it. The round-island road is faster; field banks and docks slow you down automatically.'},{titleEn:"View and zoom",bodyEn:'Drag the screen or press Q / R to turn the view; scroll to zoom. The camera moves in when you enter a village and back out when you leave. "Menu" at the bottom right resets or adjusts the view, or turns the guide arrow off.'},{titleEn:"Interact and notebook",bodyEn:"When close, press E (or F, Space), or tap the prompt. Click someone or something to gather nearby to walk over and talk or gather. Press J or tap the top right to open the notebook; tap the minimap to travel around the island."},{titleEn:"Party and quests",bodyEn:"Press 1 / 2 / 3 or tap a portrait at the top left to switch between the Tao man, Tao woman and traveller; press C to cycle. Press L for the quests page. Progress saves automatically in this device's browser."}]},minigames:{taro:{titleEn:"Taro harvest  soli",descEn:`Tap "Now!" when the marker is in the green zone. This is a teaching field — please don't walk on other people's field banks.`,milestone:{titleEn:"First taro harvest",bodyEn:"soli was added to your notebook."},success:{titleEn:"Harvest done",bodyEn:"Taro (soli) added to traditional foods."},fail:{titleEn:"Try again",bodyEn:"The rhythm was off. The water's still cool — get closer to the field bank and try again."}},fish:{titleEn:"Flying fish leap  alibangbang",descEn:"Catch the moment a flying fish leaps. This is just a practice spot at the harbour, not a crew's torch fishing.",milestone:{titleEn:"The sea in flying fish season",bodyEn:"alibangbang was added to your notebook."},success:{titleEn:"Perfect timing",bodyEn:"Flying fish (alibangbang) added to traditional foods."},fail:{titleEn:"Try again",bodyEn:"The flying fish has dropped back into the water. Wait for the next leap."}}},text:{startTitleEn:"Set foot on Pongso no Tao",startBodyEn:"Milestone saved in your notebook. Press J or tap the top right to have a look.",startErrorTitleEn:"Can't start",startErrorBodyEn:"Something went wrong at the start. Refresh the page and give it another go.",visitorWhoEn:"Kaiyuan Harbour",originWhoEn:"Wind of {name}",allTimesTitleEn:"Four lights of the island",allTimesBodyEn:"You've seen dawn, day, dusk and night.",allSeasonsTitleEn:"A full year",allSeasonsBodyEn:"You've been through the fish-calling festival, flying fish season, end-of-eating festival and the off-season.",journalUpdateTitleEn:"Notebook updated",journalGlossaryEn:"Tao word cards ×{n}",journalRecipesEn:"Recipes / health station notes",journalIngredientsEn:"Food",talkPromptEn:"Talk to {name}",placeHintEn:"Wander around the village square and have a chat with an elder or the people by the pavilion.",clinicWhoEn:"Lanyu Health Station nurse",lookWhoEn:"South coast view",fisherWhoEn:"Fisher on the boat beach",fallbackLineEn:"(They smile and nod, and don't say more for now.)",scooterOnTitleEn:"On the e-scooter",scooterOnBodyEn:'Much quicker on the round-island road; it slows down by itself on taro field banks and docks. Press M or tap "Walk | Scooter" to switch.',scooterOffTitleEn:"Walking",scooterOffBodyEn:'On foot now. Want to ride again? Press M or tap "Walk | Scooter" once more.',travelTitleEn:"Arrived at {name}",travelBodyEn:"You're here! Hop on the scooter and follow the round-island road to keep exploring."}}};export{e as default};
